}

fn parse_map_level(s: &str) -> Result<(String,String), String> {
    let parts: Vec<&str> = s.splitn(2, '=').collect();
    if parts.len()!=2 { return Err(format!("invalid map-level '{}'", s)); }
    Ok((parts[0].to_string(), parts[1].to_string()))
}

#[derive(Debug, Deserialize, Default)]
struct ConfigFile {
    message_keys: Option<Vec<String>>,
    time_keys: Option<Vec<String>>,
    level_keys: Option<Vec<String>>,
    dump_all_exclude: Option<Vec<String>>,
    always_print_fields: Option<Vec<String>>,
    main_line_format: Option<String>,
    additional_value_format: Option<String>,
    level_map: Option<HashMap<String, String>>,
}

#[derive(Debug, Clone)]
struct Config {
    message_keys: Vec<String>,
    time_keys: Vec<String>,
    level_keys: Vec<String>,
    dump_all_exclude: Vec<String>,
    always_print_fields: Vec<String>,
    main_line_format: String,
    additional_value_format: String,
    level_map: HashMap<String, String>, // lowercased from -> to (original case preserved for display? but mapping uses original value lower?)
}

impl Default for Config {
    fn default() -> Self {
        Self {
            message_keys: vec!["short_message".into(), "msg".into(), "message".into()],
            time_keys: vec!["timestamp".into(), "time".into(), "@timestamp".into()],
            dump_all_exclude: vec![],
            always_print_fields: vec![],
            level_keys: vec!["level".into(), "severity".into(), "log.level".into(), "loglevel".into()],
            main_line_format: "{{bold(fixed_size 19 fblog_timestamp)}} {{level_style (uppercase (fixed_size 5 fblog_level))}}:{{#if fblog_prefix}} {{bold(cyan fblog_prefix)}}{{/if}} {{fblog_message}}".into(),
            additional_value_format: "{{bold (color_rgb 150 150 150 (min_size 25 key))}}: {{value}}".into(),
            level_map: HashMap::new(),
        }
    }
}

fn load_config(args: &Args) -> Config {
    let mut cfg = Config::default();
    // try load config file: precedence XDG_CONFIG_HOME > HOME
    // If args.config_file provided, use that
    // Else try to find config

    let mut config_toml_opt: Option<String> = None;
    if let Some(p) = &args.config_file {
        match std::fs::read_to_string(p) {
            Ok(s) => config_toml_opt = Some(s),
            Err(_) => {
                eprintln!("");
                panic!("Could not load config file.");
            }
        }
    } else {
        // Check XDG_CONFIG_HOME/fblog.toml, then HOME/.config/fblog.toml
        // Also check HOME/.config/fblog.toml? According to tests only those two.
        // From earlier tests: XDG takes precedence over HOME, and nested fblog/fblog.toml not considered.
        // Also if XDG_CONFIG_HOME is set, don't fallback to HOME.
        let mut tried_xdg = false;
        if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
            tried_xdg = true;
            let path = PathBuf::from(xdg).join("fblog.toml");
            if path.exists() {
                if let Ok(s) = std::fs::read_to_string(&path) {
                    config_toml_opt = Some(s);
                }
            }
            // If not found and XDG set, don't fallback? According to test, when XDG set to empty dir, HOME not used. So if XDG var present, we should not try HOME.
        }
        if config_toml_opt.is_none() && !tried_xdg {
            if let Some(home) = dirs::config_dir() {
                // config_dir already is XDG_CONFIG_HOME or HOME/.config
                // It should be $HOME/.config when XDG not set
                let path = home.join("fblog.toml");
                if path.exists() {
                    if let Ok(s) = std::fs::read_to_string(&path) {
                        config_toml_opt = Some(s);
                    }
                }
            }
        }
        // Also note: when XDG var is not set, dirs::config_dir returns HOME/.config, so above covers HOME case.
        // What about HOME env set explicitly but not via dirs? dirs uses HOME? For simplicity we already handled HOME via config_dir which uses HOME.

        // Additional fallback: try $HOME/.config/fblog.toml directly even if config_dir didn't? Already.
        // For our earlier test, when HOME=/tmp/dirsTest/home and XDG unset, it found config. That matches config_dir behaviour.

    }

    if let Some(toml_str) = config_toml_opt {
        let parsed: Result<ConfigFile, _> = toml::from_str(&toml_str);
        match parsed {
            Ok(cf) => {
                if let Some(v) = cf.message_keys { cfg.message_keys = v; }
                if let Some(v) = cf.time_keys { cfg.time_keys = v; }
                if let Some(v) = cf.level_keys { cfg.level_keys = v; }
                if let Some(v) = cf.dump_all_exclude { cfg.dump_all_exclude = v; }
                if let Some(v) = cf.always_print_fields { cfg.always_print_fields = v; }
                if let Some(v) = cf.main_line_format { cfg.main_line_format = v; }
                if let Some(v) = cf.additional_value_format { cfg.additional_value_format = v; }
                if let Some(m) = cf.level_map {
                    for (k,v) in m { cfg.level_map.insert(k, v); }
                }
            },
            Err(e) => {
                // Panic as original
                panic!("Could not parse config file: {}", e);
            }
        }
    }

    // Apply CLI overrides for formats if provided (they override config)
    // But message_keys, etc from CLI are additive? From earlier tests: -m etc prepend custom keys before default.
    // Actually we saw -m custom gave custom first, then defaults? Let's test: we had -m custom with msg existing, it used custom. For -m a -m b with a and b both present, first -m wins. And default keys still considered after custom? Need to check.
    // For message_keys, default are short_message, msg, message. When we do -m custom, does it search custom then short_message, msg, message? In test: {"msg":"M","custom":"C"} with -m custom gave C, so custom first. What about {"short_message":"S","custom":"C"} with -m custom? It gave C (custom first). What about {"msg":"M"} with -m custom (custom not present) gave M (fallback to default). So -m prepends.
    // Similarly for -t and -l.

    // We'll handle later in args merging.

    // Apply --map-level CLI: these override config level_map
    for (from,to) in &args.map_level {
        cfg.level_map.insert(from.clone(), to.clone());
    }

    cfg
}

// Represents a flattened leaf
#[derive(Debug, Clone)]
struct FlatEntry {
    key: String,
    value: serde_json::Value,
    // For sorting, we have key
}

// Path parsing for additional values and excluded values and config keys (dot vs >)
// Additional values: syntax "key > nested > a[0][1]" etc.

#[derive(Debug, Clone)]
struct Segment {
    key: String, // may be empty if only indices? but first segment key maybe empty? Actually "[0]" alone? Not typical but could be.
    indices: Vec<usize>, // as given in string (raw numbers)
}

fn parse_additional_path(s: &str) -> Option<Vec<Segment>> {
    if s.trim().is_empty() {
        return None;
    }
    // Split by " > " exactly (single space)
    // But note: if string contains " > " inside? Unclear. Use split.
    let parts: Vec<&str> = s.split(" > ").collect();
    // If any part empty, fail? Let's allow but check.
    let mut segs = Vec::new();
    for part in parts {
        if part.is_empty() {
            return None;
        }
        // Parse key and indices
        // Find first '['
        let bracket_pos = part.find('[');
        let key = if let Some(pos) = bracket_pos {
            part[..pos].to_string()
        } else {
            part.to_string()
        };
        let mut indices = Vec::new();
        let mut rest = if let Some(pos) = bracket_pos { &part[pos..] } else { "" };
        // rest should be sequence of [number]
        // Use regex? Manual
        while !rest.is_empty() {
            if !rest.starts_with('[') {
                return None;
            }
            let end = rest.find(']')?;
            let num_str = &rest[1..end];
            if num_str.is_empty() {
                return None;
            }
            // parse usize, must be digits
            if !num_str.chars().all(|c| c.is_ascii_digit()) {
                return None;
            }
            let num: usize = num_str.parse().ok()?;
            indices.push(num);
            rest = &rest[end+1..];
        }
        segs.push(Segment { key, indices });
    }
    Some(segs)
}

// Get sub-value by additional path
fn get_by_additional_path(root: &serde_json::Value, path_str: &str) -> Option<serde_json::Value> {
    let segs = parse_additional_path(path_str)?;
    let mut cur = root;
    let mut arr_depth = 0usize;
    for seg in segs {
        if !seg.key.is_empty() {
            match cur {
                serde_json::Value::Object(map) => {
                    if let Some(v) = map.get(&seg.key) {
                        cur = v;
                    } else {
                        return None;
                    }
                },
                _ => return None,
            }
            arr_depth = 0;
        }
        for idx_raw in seg.indices {
            match cur {
                serde_json::Value::Array(arr) => {
                    let actual = if arr_depth==0 { idx_raw } else { if idx_raw==0 { return None; } else { idx_raw-1 } };
                    if actual >= arr.len() {
                        return None;
                    }
                    cur = &arr[actual];
                    arr_depth += 1;
                },
                _ => return None,
            }
        }
    }
    Some(cur.clone())
}

// Flatten value for display
fn flatten_value(val: &serde_json::Value, path: &str, depth: usize, out: &mut Vec<FlatEntry>) {
    match val {
        serde_json::Value::Object(map) => {
            // sorted keys
            let mut keys: Vec<&String> = map.keys().collect();
            keys.sort();
            for k in keys {
                let child = map.get(k).unwrap();
                let new_path = if path.is_empty() { k.clone() } else { format!("{} > {}", path, k) };
                // Recursively flatten, resetting depth to 0
                flatten_value(child, &new_path, 0, out);
            }
        },
        serde_json::Value::Array(arr) => {
            for (i, elem) in arr.iter().enumerate() {
                let idx = if depth==0 { i } else { i+1 };
                // Note: if depth!=0, idx is 1-based, but original python code used 1-based for depth>0.
                // However for first array level depth==0, idx is 0-based.
                // For second level depth==1, idx = i+1 (1-based)
                let elem_path = if path.is_empty() { format!("[{}]", idx) } else { format!("{}[{}]", path, idx) };
                match elem {
                    serde_json::Value::Object(_) => {
                        flatten_value(elem, &elem_path, 0, out);
                    },
                    serde_json::Value::Array(_) => {
                        flatten_value(elem, &elem_path, depth+1, out);
                    },
                    _ => {
                        out.push(FlatEntry { key: elem_path, value: elem.clone() });
                    }
                }
            }
        },
        _ => {
            // primitive: leaf
            out.push(FlatEntry { key: path.to_string(), value: val.clone() });
        }
    }
}

// For config key extraction (dot notation)
fn get_by_config_key(root: &serde_json::Value, key: &str) -> Option<serde_json::Value> {
    // Try literal first
    if let serde_json::Value::Object(map) = root {
        if let Some(v) = map.get(key) {
            if !v.is_null() {
                return Some(v.clone());
            } else {
                // If null, treat as not found? Original seems to skip null? For message keys, if value null should not be considered?
                // Let's check: dump-all excluded nulls unless? In earlier test -d for null gave no additional entries for null? Actually null in dump-all was excluded.
                // For config key extraction, if value is null, should be considered not found? Probably need to check.
                // We'll treat null as not found for message/time/level?
                // Let's return None if null.
            }
        }
    }
    // Try dot traversal
    let parts: Vec<&str> = key.split('.').collect();
    if parts.len()<=1 {
        // single part, literal already checked, so None
        return None;
    }
    let mut cur = root;
    for part in parts {
        match cur {
            serde_json::Value::Object(map) => {
                if let Some(v) = map.get(part) {
                    cur = v;
                } else {
                    return None;
                }
            },
            _ => return None,
        }
    }
    if cur.is_null() {
        return None;
    }
    Some(cur.clone())
}

fn main() {}
RS
