#[derive(Debug, Clone)]
struct Segment {
    key: String, // may be empty if only indices? but first segment key maybe empty? Actually "[0]" alone? Not typical but could be.
    indices: Vec<usize>, // as given in string (raw numbers)
}

fn parse_additional_path(s: &str) -> Option<Vec<Segment>> {
    if s.trim().is_empty() {
        return None;
    }
    // Split by " > " exactly (single space)
    // But note: if string contains " > " inside? Unclear. Use split.
    let parts: Vec<&str> = s.split(" > ").collect();
    // If any part empty, fail? Let's allow but check.
    let mut segs = Vec::new();
    for part in parts {
        if part.is_empty() {
            return None;
        }
        // Parse key and indices
        // Find first '['
        let bracket_pos = part.find('[');
        let key = if let Some(pos) = bracket_pos {
            part[..pos].to_string()
        } else {
            part.to_string()
        };
        let mut indices = Vec::new();
        let mut rest = if let Some(pos) = bracket_pos { &part[pos..] } else { "" };
        // rest should be sequence of [number]
        // Use regex? Manual
        while !rest.is_empty() {
            if !rest.starts_with('[') {
                return None;
            }
            let end = rest.find(']')?;
            let num_str = &rest[1..end];
            if num_str.is_empty() {
                return None;
            }
            // parse usize, must be digits
            if !num_str.chars().all(|c| c.is_ascii_digit()) {
                return None;
            }
            let num: usize = num_str.parse().ok()?;
            indices.push(num);
            rest = &rest[end+1..];
        }
        segs.push(Segment { key, indices });
    }
    Some(segs)
}

// Get sub-value by additional path
fn get_by_additional_path(root: &serde_json::Value, path_str: &str) -> Option<serde_json::Value> {
    let segs = parse_additional_path(path_str)?;
    let mut cur = root;
    let mut arr_depth = 0usize;
    for seg in segs {
        if !seg.key.is_empty() {
            match cur {
                serde_json::Value::Object(map) => {
                    if let Some(v) = map.get(&seg.key) {
                        cur = v;
                    } else {
                        return None;
                    }
                },
                _ => return None,
            }
            arr_depth = 0;
        }
        for idx_raw in seg.indices {
            match cur {
                serde_json::Value::Array(arr) => {
                    let actual = if arr_depth==0 { idx_raw } else { if idx_raw==0 { return None; } else { idx_raw-1 } };
                    if actual >= arr.len() {
                        return None;
                    }
                    cur = &arr[actual];
                    arr_depth += 1;
                },
                _ => return None,
            }
        }
    }
    Some(cur.clone())
}

// Flatten value for display
fn flatten_value(val: &serde_json::Value, path: &str, depth: usize, out: &mut Vec<FlatEntry>) {
    match val {
        serde_json::Value::Object(map) => {
            // sorted keys
            let mut keys: Vec<&String> = map.keys().collect();
            keys.sort();
            for k in keys {
                let child = map.get(k).unwrap();
                let new_path = if path.is_empty() { k.clone() } else { format!("{} > {}", path, k) };
                // Recursively flatten, resetting depth to 0
                flatten_value(child, &new_path, 0, out);
            }
        },
        serde_json::Value::Array(arr) => {
            for (i, elem) in arr.iter().enumerate() {
                let idx = if depth==0 { i } else { i+1 };
                // Note: if depth!=0, idx is 1-based, but original python code used 1-based for depth>0.
                // However for first array level depth==0, idx is 0-based.
                // For second level depth==1, idx = i+1 (1-based)
                let elem_path = if path.is_empty() { format!("[{}]", idx) } else { format!("{}[{}]", path, idx) };
                match elem {
                    serde_json::Value::Object(_) => {
                        flatten_value(elem, &elem_path, 0, out);
                    },
                    serde_json::Value::Array(_) => {
                        flatten_value(elem, &elem_path, depth+1, out);
                    },
                    _ => {
                        out.push(FlatEntry { key: elem_path, value: elem.clone() });
                    }
                }
            }
        },
        _ => {
            // primitive: leaf
            out.push(FlatEntry { key: path.to_string(), value: val.clone() });
        }
    }
}

