// Template engine (simplified handlebars-like)
// We need to support helpers: bold, cyan, red, green, yellow, blue, purple, color_rgb, fixed_size, min_size, uppercase, level_style, and #if
// Syntax: {{helper arg}} or {{helper (helper arg)}} or {{#if condition}}...{{/if}} or {{#if cond}}...{{else}}...{{/if}}? Need to check if else supported? The default template uses {{#if fblog_prefix}} ... {{/if}} without else. We tested {{#if fblog_prefix}}has{{/if}} works. Does else work?
// We can attempt to support #if with else.
// Also helpers can be nested: {{bold (color_rgb 150 150 150 (min_size 25 key))}} etc.
// So we need to parse handlebars expression.

#[derive(Debug, Clone)]
enum TemplateNode {
    Text(String),
    Variable(String), // e.g., fblog_message
    Helper { name: String, args: Vec<TemplateNode> }, // helper with args (each arg is a node that evaluates to string)
    If { condition: String, then_branch: Vec<TemplateNode>, else_branch: Option<Vec<TemplateNode>> },
}

fn parse_template(s: &str) -> Result<Vec<TemplateNode>, String> {
    // Simple parser for handlebars subset.
    // Iterate finding {{ and }}
    let mut nodes = Vec::new();
    let mut chars = s.chars().peekable();
    let mut text_buf = String::new();
    let mut idx = 0usize;
    let s_bytes = s.as_bytes();
    let mut i = 0usize;
    while i < s.len() {
        if s[i..].starts_with("{{") {
            if !text_buf.is_empty() {
                nodes.push(TemplateNode::Text(text_buf.clone()));
                text_buf.clear();
            }
            // find closing }}
            let start = i+2;
            if let Some(end) = s[start..].find("}}") {
                let inner = s[start..start+end].trim();
                // Parse inner
                if inner.starts_with("#if") {
                    // #if condition
                    let cond = inner[3..].trim().to_string();
                    // Need to find matching {{/if}} and optional {{else}}
                    // For simplicity, parse the rest of template after this tag to find if block.
                    // We'll need to handle nested ifs? Could be nested? Probably but we can handle simple.
                    // Find the content until {{/if}}
                    let after_if_start = start+end+2;
                    let remaining = &s[after_if_start..];
                    // Find {{else}} and {{/if}} positions
                    // This is more complex; we need to parse recursively.

                    // For our implementation, we will parse using a stack approach.
                    // Instead of handling here, we will implement a full parser that iterates and handles if.
                    // To do that, we need to re-implement parse_template as recursive.

                    // As a quick workaround, we will implement a separate function parse_with_if that handles.
                    // For now, placeholder: we will attempt to find else and endif.

                    // Since we are inside loop, we need to parse block content.

                    // Let's delegate to a function that parses from after_if_start and returns then_branch, else_branch, new position.

                    // We'll use internal helper parse_until_endif.

                    let (then_nodes, else_nodes, new_pos) = parse_if_block(&s[after_if_start..])?;
                    nodes.push(TemplateNode::If { condition: cond, then_branch: then_nodes, else_branch: else_nodes });
                    i = after_if_start + new_pos;
                    continue;
                } else if inner.starts_with("/if") {
                    return Err(format!("unexpected /if at position {}", i));
                } else if inner == "else" {
                    return Err(format!("unexpected else at position {}", i));
                } else {
                    // Helper or variable
                    // Parse helper call: helper_name (args) or helper_name arg1 arg2 ...
                    // The syntax supports nested: {{bold (color_rgb 150 150 150 (min_size 25 key))}}
                    // So we need to parse expression with possible subexpressions in parentheses.
                    // We'll parse inner into nodes.

                    let node = parse_helper_expr(inner)?;
                    nodes.push(node);
                    i = start + end + 2;
                    continue;
                }
            } else {
                return Err(format!("unclosed {{ at {}", i));
            }
        } else {
            text_buf.push(s[i..].chars().next().unwrap());
            // advance by char length
            let ch_len = s[i..].chars().next().unwrap().len_utf8();
            i += ch_len;
            continue;
        }
    }
    if !text_buf.is_empty() {
        nodes.push(TemplateNode::Text(text_buf));
    }
    Ok(nodes)
}

fn parse_if_block(s: &str) -> Result<(Vec<TemplateNode>, Option<Vec<TemplateNode>>, usize), String> {
    // s is content after {{#if cond}}
    // We need to parse until matching {{/if}}, handling {{else}} at same level.
    // We will scan for {{#if, {{/if}}, {{else}} tags.
    let mut depth = 0usize;
    let mut i = 0usize;
    let mut then_end = None;
    let mut else_start = None;
    let mut else_end = None;
    while i < s.len() {
        if s[i..].starts_with("{{") {
            let start = i+2;
            if let Some(end) = s[start..].find("}}") {
                let inner = s[start..start+end].trim();
                if inner.starts_with("#if") {
                    depth += 1;
                } else if inner.starts_with("/if") {
                    if depth==0 {
                        // Found our endif
                        let then_content = &s[..i];
                        // Determine else position
                        if let Some(es) = else_start {
                            let ee = else_end.unwrap();
                            let then_part = &s[..es];
                            let else_part = &s[ee..i];
                            let then_nodes = parse_template(then_part)?;
                            let else_nodes = parse_template(else_part)?;
                            return Ok((then_nodes, Some(else_nodes), start+end+2));
                        } else {
                            let then_nodes = parse_template(then_content)?;
                            return Ok((then_nodes, None, start+end+2));
                        }
                    } else {
                        depth -= 1;
                    }
                } else if inner == "else" && depth==0 {
                    // else at current level
                    else_start = Some(i);
                    // Actually else start is position of {{else}} start, then_end is previous content before else
                    // Record where else block starts after the tag
                    let after_else = start+end+2;
                    else_end = Some(after_else);
                }
                i = start + end + 2;
                continue;
            } else {
                return Err("unclosed {{ in if block".into());
            }
        } else {
            let ch_len = s[i..].chars().next().unwrap().len_utf8();
            i += ch_len;
        }
    }
    Err("missing {{/if}}".into())
}

fn parse_helper_expr(s: &str) -> Result<TemplateNode, String> {
    let s = s.trim();
    if s.is_empty() { return Err("empty expression".into()); }
    // Check if it's a simple variable (no spaces, no parens)
    // Helper names are alphabetic + underscore
    // If contains spaces, first token is helper name, rest are args
    // Args can be subexpressions like (color_rgb ...) or simple variables/numbers

    // To parse, we need to tokenize respecting parentheses.
    // Example: "bold (color_rgb 150 150 150 (min_size 25 key))"
    // Should parse as helper bold with one arg which is helper color_rgb...

    // Simple approach: if starts with '(' and ends with ')', strip and parse inner?
    // But spec: {{bold (fixed_size 19 fblog_timestamp)}} -> inner of bold is "(fixed_size 19 fblog_timestamp)" which itself is helper call inside parens.

    // So parse_helper_expr should handle:
    // - Variable: "fblog_message" => Variable node
    // - Helper call: "bold fblog_message" -> helper bold with arg Variable
    // - Helper call with parens: "bold (fixed_size 19 fblog_timestamp)" -> helper bold with arg = helper fixed_size

    // Implementation: tokenization that splits by spaces but keeps parenthesized groups as tokens.

    // We'll write a function parse_tokens that returns Vec<String> where each token is either plain or parenthesized expression.

    // Example: "color_rgb 150 150 150 (min_size 25 key)"
    // tokens: ["color_rgb","150","150","150","(min_size 25 key)"]

    // Then first token is helper name, rest are args (each arg parsed recursively if parenthesized or number/string? Numbers as text? Variables as text? For helpers like fixed_size 19, second arg is number "19", third is variable.

    // We'll implement recursion: if token is parenthesized, strip outer parens and parse as helper expr recursively.

    // If token is not parenthesized, it's either variable name or literal number? For our evaluation, we will treat as string that could be variable name, but for numbers we need to preserve.

    // Also color_rgb takes 3 numbers + value: "color_rgb 150 150 150 key"

    // Let's implement.

    let tokens = tokenize_helper(s)?;
    if tokens.is_empty() { return Err("no tokens".into()); }
    if tokens.len()==1 {
        // Single token: could be variable or number?
        let tok = &tokens[0];
        if tok.starts_with('(') && tok.ends_with(')') {
            // subexpression
            let inner = &tok[1..tok.len()-1].trim();
            return parse_helper_expr(inner);
        } else {
            // Check if it's a number? For our purposes, variable nodes can hold number strings? But for evaluation we will check.
            return Ok(TemplateNode::Variable(tok.clone()));
        }
    } else {
        // First token is helper name
        let name = tokens[0].clone();
        let mut args = Vec::new();
        for tok in tokens.iter().skip(1) {
            if tok.starts_with('(') && tok.ends_with(')') {
                let inner = &tok[1..tok.len()-1];
                let node = parse_helper_expr(inner)?;
                args.push(node);
            } else {
                args.push(TemplateNode::Variable(tok.clone()));
            }
        }
        return Ok(TemplateNode::Helper { name, args });
    }
}

fn tokenize_helper(s: &str) -> Result<Vec<String>, String> {
    let mut tokens = Vec::new();
    let mut i = 0usize;
    let chars: Vec<char> = s.chars().collect();
    while i < chars.len() {
        while i < chars.len() && chars[i].is_whitespace() { i+=1; }
        if i>=chars.len() { break; }
        if chars[i]=='(' {
            // Find matching ')'
            let mut depth = 0usize;
            let mut j = i;
            while j < chars.len() {
                if chars[j]=='(' { depth+=1; }
                else if chars[j]==')' { depth-=1; if depth==0 { break; } }
                j+=1;
            }
            if depth!=0 { return Err("unmatched paren".into()); }
            // token from i to j inclusive
            let token: String = chars[i..=j].iter().collect();
            tokens.push(token);
            i = j+1;
        } else {
            // Read until whitespace or '('
            let mut j = i;
            while j < chars.len() && !chars[j].is_whitespace() && chars[j]!='(' {
                j+=1;
            }
            let token: String = chars[i..j].iter().collect();
            tokens.push(token);
            i = j;
        }
    }
    Ok(tokens)
}

