                    // Re-evaluate with exact table
                    let exact_color = match low.as_str() {
                        "trace" => "\x1b[1;36m",
                        "debug" => "\x1b[1;34m",
                        "info" => "\x1b[1;32m",
                        "warn" => "\x1b[1;33m",
                        "warning" => "\x1b[1;33m",
                        "error" => "\x1b[1;31m",
                        "err" => "\x1b[1;31m",
                        "fatal" => "\x1b[1;35m",
                        _ => {
                            // For unknown, use bold magenta? Original for unknown used 1;35
                            "\x1b[1;35m"
                        }
                    };

                    // But what about level strings that are numeric like "10"? Those should be treated as unknown -> magenta.

                    Ok(format!("{}{}\x1b[0m", exact_color, lvl))
                },
                _ => {
                    return Err(format!("Helper not found {}", name));
                }
            }
        },
        TemplateNode::If { condition, then_branch, else_branch } => {
            // condition is variable name like "fblog_prefix"
            let cond_val = ctx.get(condition).map(|s| !s.is_empty()).unwrap_or(false);
            if cond_val {
                eval_template(then_branch, ctx)
            } else {
                if let Some(else_branch) = else_branch {
                    eval_template(else_branch, ctx)
                } else {
                    Ok("".to_string())
                }
            }
        },
    }
}

fn render_template(template_str: &str, ctx: &HashMap<String,String>) -> Result<String, String> {
    let nodes = parse_template(template_str).map_err(|e| format!("Template invalid: {}", e))?;
    eval_template(&nodes, ctx)
}

