// Let's implement filter evaluator.

#[derive(Debug, Clone, PartialEq)]
enum FilterValue {
    Nil,
    Bool(bool),
    Number(f64),
    String(String),
    Table(HashMap<String, FilterValue>), // for nested objects
    Array(Vec<FilterValue>), // Lua arrays 1-based
}

impl FilterValue {
    fn is_truthy(&self) -> bool {
        match self {
            FilterValue::Nil => false,
            FilterValue::Bool(b) => *b,
            _ => true, // In Lua, only nil and false are falsy
        }
    }
}

fn json_to_filter_value(v: &Value) -> FilterValue {
    match v {
        Value::Null => FilterValue::Nil,
        Value::Bool(b) => FilterValue::Bool(*b),
        Value::Number(n) => {
            if let Some(f) = n.as_f64() {
                FilterValue::Number(f)
            } else { FilterValue::Nil }
        },
        Value::String(s) => FilterValue::String(s.clone()),
        Value::Object(map) => {
            let mut tbl = HashMap::new();
            for (k,child) in map {
                // sanitize key for lua variable: replace non-alphanumeric with underscore? Example "@version" -> "_version", "fields.time" -> "fields_time", "my-key" -> "my_key"
                let sanitized = sanitize_key(k);
                tbl.insert(sanitized, json_to_filter_value(child));
                // Also include original? For our purpose, we will insert both sanitized and original? But original may contain dot for nested? Actually for object, we need nested table access: e.g., status.a -> status table contains a.
                // So we also keep nested structure as table where field names are sanitized? Wait status.a: status is table, a is its field. For "fields.time" literal key, we want fields_time as top-level variable, not nested. So we will insert literal sanitized as top-level? Actually our approach for json_to_filter_value converts object recursively into table where keys are sanitized original keys (not split dot). So {"fields.time":"13ms"} would become table with key "fields_time" -> value. That's correct for filter that uses fields_time.
                // For nested {"fields":{"time":"nested"}}, it would be table: fields -> table { time -> nested }
                // For literal {"fields.time":"lit"}, top-level would have fields_time already.
                // So json_to_filter_value handles both: object keys sanitized, nested objects become subtables.
                // However for config key "log.level" literal vs nested, we handled literal first. For filter, similar?
            }
            // Also need to handle that the top-level filter context should have flattened? Actually for filter, they expose variables as per json structure: e.g., {"a":{"b":5}} => filter a.b ==5 works. That suggests top-level context contains a table a with b field. Our conversion does that: root object converted to table with key "a" -> table { b -> 5 }. So a.b works.

            // Also need to handle that for root, we shouldn't just return table but set its fields as variables in Lua globals. So our filter evaluation will have globals = root table's entries.

            FilterValue::Table(tbl)
        },
        Value::Array(arr) => {
            let mut vec = Vec::new();
            for elem in arr {
                vec.push(json_to_filter_value(elem));
            }
            FilterValue::Array(vec)
        },
    }
}

fn sanitize_key(k: &str) -> String {
    let mut out = String::new();
    for (i,ch) in k.chars().enumerate() {
        if ch.is_ascii_alphanumeric() || ch=='_' {
            out.push(ch);
        } else {
            out.push('_');
        }
    }
    // If starts with digit, prepend underscore? Lua variables cannot start with digit.
    if out.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false) {
        out = format!("_{}", out);
    }
    // If empty, use "_"
    if out.is_empty() { out = "_".into(); }
    out
}

// Now we need to parse filter expression into AST.

// Lua subset needed:
// - Literals: nil, true, false, numbers, strings in double or single quotes
// - Variables: identifier, possibly dotted: a.b, a.b.c, fields_time, etc.
// - Array indexing: a[1], a[1][2], etc.
// - Operators: ==, ~=, <, >, <=, >=, and, or, not, .. (concat?), +, -, *, /, %? For our purposes, we need ==, ~=, and, or, not, <, >, <=, >=
// - Function call: string.find(s, pattern)
// - Parentheses
// - return statement optionally prepended unless --no-implicit-filter-return-statement

// We'll implement a simple recursive descent parser.

#[derive(Debug, Clone, PartialEq)]
enum BinOp { Eq, NotEq, Lt, Gt, Le, Ge, And, Or, Add, Sub, Mul, Div, Mod, Concat }

#[derive(Debug, Clone, PartialEq)]
enum UnOp { Not, Neg }

#[derive(Debug, Clone)]
enum Expr {
    Nil,
    Bool(bool),
    Number(f64),
    Str(String),
    Var(String), // with dots maybe represented as path?
    FieldAccess { base: Box<Expr>, field: String }, // a.b
    Index { base: Box<Expr>, index: Box<Expr> }, // a[expr]
    Unary { op: UnOp, expr: Box<Expr> },
    Binary { op: BinOp, left: Box<Expr>, right: Box<Expr> },
    Call { func: String, args: Vec<Expr> }, // only string.find for now, but also we might see other calls?
}

struct FilterParser {
    input: Vec<char>,
    pos: usize,
}

impl FilterParser {
    fn new(s: &str) -> Self { Self { input: s.chars().collect(), pos:0 } }
    fn peek(&self) -> Option<char> { self.input.get(self.pos).cloned() }
    fn peek_next(&self) -> Option<char> { self.input.get(self.pos+1).cloned() }
    fn consume(&mut self) -> Option<char> { if self.pos < self.input.len() { let c=self.input[self.pos]; self.pos+=1; Some(c) } else { None } }
    fn skip_ws(&mut self) { while let Some(c)=self.peek() { if c.is_whitespace() { self.pos+=1; } else { break; } } }
    fn expect(&mut self, ch: char) -> Result<(), String> { self.skip_ws(); if self.peek()==Some(ch) { self.pos+=1; Ok(()) } else { Err(format!("expected '{}'", ch)) } }
    fn parse(&mut self) -> Result<Expr, String> {
        self.skip_ws();
        let e = self.parse_or()?;
        self.skip_ws();
        if self.pos < self.input.len() {
            Err(format!("unexpected token at pos {}", self.pos))
        } else { Ok(e) }
    }
    fn parse_or(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_and()?;
        loop {
            self.skip_ws();
            if self.match_word("or") {
                let right = self.parse_and()?;
                left = Expr::Binary { op: BinOp::Or, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_and(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_comparison()?;
        loop {
            self.skip_ws();
            if self.match_word("and") {
                let right = self.parse_comparison()?;
                left = Expr::Binary { op: BinOp::And, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_comparison(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_concat()?;
        loop {
            self.skip_ws();
            let op = if self.match_str("==") { Some(BinOp::Eq) }
            else if self.match_str("~=") { Some(BinOp::NotEq) }
            else if self.match_str("<=") { Some(BinOp::Le) }
            else if self.match_str(">=") { Some(BinOp::Ge) }
            else if self.match_str("<") { Some(BinOp::Lt) }
            else if self.match_str(">") { Some(BinOp::Gt) }
            else { None };
            if let Some(op) = op {
                let right = self.parse_concat()?;
                left = Expr::Binary { op, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_concat(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_add_sub()?;
        loop {
            self.skip_ws();
            if self.match_str("..") {
                let right = self.parse_add_sub()?;
                left = Expr::Binary { op: BinOp::Concat, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_add_sub(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_mul_div()?;
        loop {
            self.skip_ws();
            if self.match_str("+") {
                let right = self.parse_mul_div()?;
                left = Expr::Binary { op: BinOp::Add, left: Box::new(left), right: Box::new(right) };
            } else if self.match_str("-") {
                let right = self.parse_mul_div()?;
                left = Expr::Binary { op: BinOp::Sub, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_mul_div(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_unary()?;
        loop {
            self.skip_ws();
            if self.match_str("*") {
                let right = self.parse_unary()?;
                left = Expr::Binary { op: BinOp::Mul, left: Box::new(left), right: Box::new(right) };
            } else if self.match_str("/") {
                let right = self.parse_unary()?;
                left = Expr::Binary { op: BinOp::Div, left: Box::new(left), right: Box::new(right) };
            } else if self.match_str("%") {
                let right = self.parse_unary()?;
                left = Expr::Binary { op: BinOp::Mod, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_unary(&mut self) -> Result<Expr, String> {
        self.skip_ws();
        if self.match_word("not") {
            let e = self.parse_unary()?;
            return Ok(Expr::Unary { op: UnOp::Not, expr: Box::new(e) });
        }
        if self.match_str("-") {
            let e = self.parse_unary()?;
            return Ok(Expr::Unary { op: UnOp::Neg, expr: Box::new(e) });
        }
        self.parse_primary()
    }
    fn parse_primary(&mut self) -> Result<Expr, String> {
        self.skip_ws();
        let c = self.peek().ok_or("unexpected eof")?;
        if c=='(' {
            self.consume();
            let e = self.parse_or()?;
            self.skip_ws();
            self.expect(')')?;
            // after paren, may have field access or index
            return self.parse_postfix(e);
        } else if c=='"' || c=='\'' {
            let s = self.parse_string()?;
            let expr = Expr::Str(s);
            return self.parse_postfix(expr);
        } else if c.is_ascii_digit() || (c=='.' && self.peek_next().map(|n| n.is_ascii_digit()).unwrap_or(false)) {
            let num = self.parse_number()?;
            let expr = Expr::Number(num);
            return self.parse_postfix(expr);
        } else if is_ident_start(c) {
            // identifier or keyword nil true false
            let ident = self.parse_ident()?;
            if ident=="nil" {
                return self.parse_postfix(Expr::Nil);
            } else if ident=="true" {
                return self.parse_postfix(Expr::Bool(true));
            } else if ident=="false" {
                return self.parse_postfix(Expr::Bool(false));
            } else {
                // Could be function call? Check if next non-ws is '(' and ident contains dot (e.g., string.find)
                // Actually function call parsing should be handled after identifier, but we need to support string.find
                // If ident contains '.' we already have field access? Our parse_ident will stop at '.'? Actually we need to allow '.' inside ident for our simple case? Let's parse ident as word, then handle postfix field accesses via '.' operator.

                // For function like string.find, we will have base expr Var("string"), then FieldAccess "find", then Call
                let base = Expr::Var(ident);
                let expr = self.parse_postfix(base)?;
                // Check if it's a call (if next is '(')
                self.skip_ws();
                if self.peek()==Some('(') {
                    // It's a call, need to parse args
                    // But our parse_postfix already handles indexing but not call? We'll parse call here
                    // Actually we need to parse call after postfix chain
                    // Let's handle
                    return self.parse_call(expr);
                } else {
                    return Ok(expr);
                }
            }
        } else {
            Err(format!("unexpected char '{}' at {}", c, self.pos))
        }
    }
    fn parse_postfix(&mut self, mut base: Expr) -> Result<Expr, String> {
        loop {
            self.skip_ws();
            if self.peek()==Some('.') {
                self.consume();
                let field = self.parse_ident()?;
                base = Expr::FieldAccess { base: Box::new(base), field };
            } else if self.peek()==Some('[') {
                self.consume();
                let idx_expr = self.parse_or()?;
                self.skip_ws();
                self.expect(']')?;
                base = Expr::Index { base: Box::new(base), index: Box::new(idx_expr) };
            } else {
                break;
            }
        }
        Ok(base)
    }
    fn parse_call(&mut self, func_expr: Expr) -> Result<Expr, String> {
        // func_expr should be var or field access
        // Convert to func name string if possible
        // For simplicity, we will extract func name as "string.find" etc
        let func_name = match &func_expr {
            Expr::Var(v) => v.clone(),
            Expr::FieldAccess { base, field } => {
                // base should be Var
                if let Expr::Var(b) = base.as_ref() {
                    format!("{}.{}", b, field)
                } else {
                    // nested like a.b.c?
                    // Recursively build
                    // For simplicity, if base is FieldAccess, get its string
                    let mut parts = Vec::new();
                    let mut cur = &func_expr;
                    loop {
                        match cur {
                            Expr::FieldAccess { base, field } => {
                                parts.push(field.clone());
                                cur = base;
                            },
                            Expr::Var(v) => {
                                parts.push(v.clone());
                                break;
                            },
                            _ => return Err("invalid func name".into()),
                        }
                    }
                    parts.reverse();
                    parts.join(".")
                }
            },
            _ => return Err("invalid function expr".into()),
        };
        self.skip_ws();
        self.expect('(')?;
        let mut args = Vec::new();
        loop {
            self.skip_ws();
            if self.peek()==Some(')') {
                self.consume();
                break;
            }
            let arg = self.parse_or()?;
            args.push(arg);
            self.skip_ws();
            if self.peek()==Some(',') {
                self.consume();
                continue;
            } else if self.peek()==Some(')') {
                continue;
            } else {
                return Err(format!("expected , or ) in call"));
            }
        }
        // After call, may have postfix again (e.g., string.find(...).something?) Unlikely
        let call_expr = Expr::Call { func: func_name, args };
        self.parse_postfix(call_expr)
    }
    fn parse_string(&mut self) -> Result<String, String> {
        let quote = self.consume().unwrap();
        let mut s = String::new();
        while let Some(c) = self.consume() {
            if c==quote {
                return Ok(s);
            } else if c=='\\' {
                // handle escapes
                if let Some(esc) = self.consume() {
                    match esc {
                        'n' => s.push('\n'),
                        'r' => s.push('\r'),
                        't' => s.push('\t'),
                        '\\' => s.push('\\'),
                        '"' => s.push('"'),
                        '\'' => s.push('\''),
                        _ => { s.push('\\'); s.push(esc); }
                    }
                } else {
                    return Err("unterminated string escape".into());
                }
            } else {
                s.push(c);
            }
        }
        Err("unterminated string".into())
    }
    fn parse_number(&mut self) -> Result<f64, String> {
        let mut num_str = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c=='.' || c=='e' || c=='E' || c=='+' || c=='-' {
                // Need to be careful with + - only after e
                // For simplicity, accept
                num_str.push(c);
                self.consume();
            } else { break; }
        }
        num_str.parse::<f64>().map_err(|e| format!("invalid number {}: {}", num_str, e))
    }
    fn parse_ident(&mut self) -> Result<String, String> {
        self.skip_ws();
        let mut ident = String::new();
        if let Some(c) = self.peek() {
            if !is_ident_start(c) { return Err(format!("expected identifier, got {}", c)); }
        } else { return Err("expected identifier, got eof".into()); }
        while let Some(c) = self.peek() {
            if is_ident_continue(c) {
                ident.push(c);
                self.consume();
            } else { break; }
        }
        Ok(ident)
    }
    fn match_word(&mut self, word: &str) -> bool {
        self.skip_ws();
        let start = self.pos;
        // Check if input at pos starts with word and followed by non-ident char
        let len = word.len();
        if self.pos + len > self.input.len() { return false; }
        let substr: String = self.input[self.pos..self.pos+len].iter().collect();
        if substr != word { return false; }
        // Check boundary
        if self.pos+len < self.input.len() {
            let next = self.input[self.pos+len];
            if is_ident_continue(next) { return false; }
        }
        self.pos += len;
        true
    }
    fn match_str(&mut self, s: &str) -> bool {
        self.skip_ws();
        if s.is_empty() { return false; }
        let len = s.len();
        if self.pos+len > self.input.len() { return false; }
        let substr: String = self.input[self.pos..self.pos+len].iter().collect();
        if substr==s {
            // For operators, ensure not part of longer operator? e.g., "<" should not match "<=" already handled by checking longer first
            // We'll handle by order of checking longer first in caller
            self.pos+=len;
            true
        } else { false }
    }
}

fn is_ident_start(c: char) -> bool { c.is_ascii_alphabetic() || c=='_' }
fn is_ident_continue(c: char) -> bool { c.is_ascii_alphanumeric() || c=='_' }

fn eval_filter_expr(expr: &Expr, env: &HashMap<String, FilterValue>) -> Result<FilterValue, String> {
    match expr {
        Expr::Nil => Ok(FilterValue::Nil),
        Expr::Bool(b) => Ok(FilterValue::Bool(*b)),
        Expr::Number(n) => Ok(FilterValue::Number(*n)),
        Expr::Str(s) => Ok(FilterValue::String(s.clone())),
        Expr::Var(name) => {
            // lookup in env
            if let Some(v) = env.get(name) {
                Ok(v.clone())
            } else {
                Ok(FilterValue::Nil)
            }
        },
        Expr::FieldAccess { base, field } => {
            let base_val = eval_filter_expr(base, env)?;
            match base_val {
                FilterValue::Table(tbl) => {
                    if let Some(v) = tbl.get(field) {
                        Ok(v.clone())
                    } else {
                        Ok(FilterValue::Nil)
                    }
                },
                _ => Ok(FilterValue::Nil),
            }
        },
        Expr::Index { base, index } => {
            let base_val = eval_filter_expr(base, env)?;
            let idx_val = eval_filter_expr(index, env)?;
            match (base_val, idx_val) {
                (FilterValue::Array(arr), FilterValue::Number(n)) => {
                    let idx = n as usize;
                    // Lua 1-based
                    if idx==0 { return Ok(FilterValue::Nil); }
                    if idx>0 && idx <= arr.len() {
                        Ok(arr[idx-1].clone())
                    } else {
                        Ok(FilterValue::Nil)
                    }
                },
                (FilterValue::Table(tbl), FilterValue::String(s)) => {
                    if let Some(v) = tbl.get(&s) {
                        Ok(v.clone())
                    } else {
                        Ok(FilterValue::Nil)
                    }
                },
                (FilterValue::Table(tbl), FilterValue::Number(n)) => {
                    // number index as string key?
                    let key = (n as i64).to_string();
                    if let Some(v) = tbl.get(&key) {
                        Ok(v.clone())
                    } else {
                        Ok(FilterValue::Nil)
                    }
                },
                _ => Ok(FilterValue::Nil),
            }
        },
        Expr::Unary { op, expr } => {
            let v = eval_filter_expr(expr, env)?;
            match op {
                UnOp::Not => Ok(FilterValue::Bool(!v.is_truthy())),
                UnOp::Neg => {
                    if let FilterValue::Number(n) = v {
                        Ok(FilterValue::Number(-n))
                    } else {
                        Err(format!("attempt to negate {:?}", v))
                    }
                }
            }
        },
        Expr::Binary { op, left, right } => {
            // For and/or short-circuit
            match op {
                BinOp::And => {
                    let l = eval_filter_expr(left, env)?;
                    if !l.is_truthy() { return Ok(l); }
                    let r = eval_filter_expr(right, env)?;
                    Ok(r)
                },
                BinOp::Or => {
                    let l = eval_filter_expr(left, env)?;
                    if l.is_truthy() { return Ok(l); }
                    let r = eval_filter_expr(right, env)?;
                    Ok(r)
                },
                _ => {
                    let l = eval_filter_expr(left, env)?;
                    let r = eval_filter_expr(right, env)?;
                    eval_binary(op, l, r)
                }
            }
        },
        Expr::Call { func, args } => {
            if func=="string.find" {
                if args.len()<2 { return Err(format!("string.find needs 2 args")); }
                let s_val = eval_filter_expr(&args[0], env)?;
                let pat_val = eval_filter_expr(&args[1], env)?;
                // Expect strings
                let s = match s_val {
                    FilterValue::String(s) => s,
                    FilterValue::Nil => return Err(format!("bad argument #1 to 'find' (string expected, got nil)")),
                    _ => return Err(format!("bad argument #1 to 'find' (string expected, got {:?})", s_val)),
                };
                let pat = match pat_val {
                    FilterValue::String(p) => p,
                    _ => return Err(format!("bad argument #2 to 'find' (string expected)")),
                };
                // Lua string.find with pattern: for our purposes, treat pat as Lua pattern? But sample uses "text.*" as pattern -> should be pattern matching.
                // Implement simple: if pat contains ".*", treat as regex? Actually Lua patterns: "." matches any char, "*" is repetition, but ".*" in Lua is ".-" ? Hmm.
                // However examples: fblog -f 'message ~= nil and string.find(message, "text.*") ~= nil' . So they use Lua pattern matching.
                // For simplicity, we will try to convert Lua pattern to regex: For now, support substring search, and if pattern contains magic chars, treat as regex? Could use regex crate to handle.
                // We'll attempt to convert Lua pattern to regex: Lua pattern magic: ( ) . % + - * ? [ ^ $ .
                // For "text.*", in Lua, ".*" would be? In Lua, "." matches any, "*" zero or more of previous. So "text.*" would match "text" followed by any chars (including empty) -> essentially prefix "text". So we could use regex where "." is "." and "*" is ".*"? But Lua ".*" already is ".*"? So we can attempt to translate Lua pattern to regex by escaping and then handling.
                // Simpler: if string.find with 3rd arg nil, it does pattern matching. We'll implement as: if pattern contains Lua magic, try to use regex search; otherwise substring.

                // For minimal, implement Lua pattern matching via converting to regex:
                // Lua pattern -> regex: escape regex specials except those that are Lua magic and have regex equivalents.
                // Let's do simple: treat pat as regex directly if it contains ".*", else substring.
                // Use regex crate: try to compile pat as regex, search in s.
