                    }
                } else { false }
            };
            if truthy {
                eval_template(then_branch, ctx, json_root)
            } else {
                if let Some(else_branch) = else_branch {
                    eval_template(else_branch, ctx, json_root)
                } else {
                    Ok("".to_string())
                }
            }
        },
    }
}

fn strip_ansi(s: &str) -> String {
    // Remove ANSI escape sequences \x1b[...m
    let re = Regex::new(r"\x1b\[[0-9;]*m").unwrap();
    re.replace_all(s, "").to_string()
}

fn truncate_ansi_aware(s: &str, size: usize) -> String {
    // Truncate visible characters to size, preserving ANSI sequences? For simplicity, we will truncate based on visible chars ignoring ANSI, but keep ANSI codes that are within truncated region.
    // Implementation: iterate characters, keep track of visible count, copy ANSI codes as they appear without counting.
    let mut out = String::new();
    let mut visible = 0usize;
    let mut i = 0usize;
    let chars: Vec<char> = s.chars().collect();
    let mut in_esc = false;
    let mut esc_buf = String::new();
    while i < chars.len() && visible < size {
        let c = chars[i];
        if c == '\x1b' {
            // start escape
            in_esc = true;
            esc_buf.clear();
            esc_buf.push(c);
            i+=1;
            while i < chars.len() {
                let ec = chars[i];
                esc_buf.push(ec);
                i+=1;
                if ec == 'm' {
                    break;
                }
            }
            out.push_str(&esc_buf);
            in_esc = false;
        } else {
            out.push(c);
            visible+=1;
            i+=1;
        }
    }
    // If we truncated inside, we should not add extra
    out
}

