// Filter handling
#[derive(Debug, Clone, PartialEq)]
enum FilterValue {
    Nil,
    Bool(bool),
    Number(f64),
    String(String),
    Table(HashMap<String, FilterValue>),
    Array(Vec<FilterValue>),
}

impl FilterValue {
    fn is_truthy(&self) -> bool {
        match self {
            FilterValue::Nil => false,
            FilterValue::Bool(b) => *b,
            _ => true,
        }
    }
}

fn json_to_filter_value(v: &Value) -> FilterValue {
    match v {
        Value::Null => FilterValue::Nil,
        Value::Bool(b) => FilterValue::Bool(*b),
        Value::Number(n) => {
            if let Some(f) = n.as_f64() { FilterValue::Number(f) } else { FilterValue::Nil }
        },
        Value::String(s) => FilterValue::String(s.clone()),
        Value::Object(map) => {
            let mut tbl = HashMap::new();
            for (k, child) in map {
                let sanitized = sanitize_key(k);
                tbl.insert(sanitized, json_to_filter_value(child));
            }
            FilterValue::Table(tbl)
        },
        Value::Array(arr) => {
            let mut vec = Vec::new();
            for elem in arr {
                vec.push(json_to_filter_value(elem));
            }
            FilterValue::Array(vec)
        },
    }
}

fn sanitize_key(k: &str) -> String {
    let mut out = String::new();
    for ch in k.chars() {
        if ch.is_ascii_alphanumeric() || ch=='_' { out.push(ch); } else { out.push('_'); }
    }
    if out.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false) {
        out = format!("_{}", out);
    }
    if out.is_empty() { out = "_".into(); }
    out
}

