                if let Some(v) = cf.time_keys { cfg.time_keys = v; }
                if let Some(v) = cf.level_keys { cfg.level_keys = v; }
                if let Some(v) = cf.dump_all_exclude { cfg.dump_all_exclude = v; }
                if let Some(v) = cf.always_print_fields { cfg.always_print_fields = v; }
                if let Some(v) = cf.main_line_format { cfg.main_line_format = v; }
                if let Some(v) = cf.additional_value_format { cfg.additional_value_format = v; }
                if let Some(m) = cf.level_map {
                    for (k,v) in m { cfg.level_map.insert(k, v); }
                }
            },
            Err(e) => {
                panic!("Could not parse config file: {}", e);
            }
        }
    }
    cfg
}

#[derive(Debug, Clone)]
struct Segment {
    key: String,
    indices: Vec<usize>,
}

fn parse_additional_path(s: &str) -> Option<Vec<Segment>> {
    if s.is_empty() { return None; }
    let parts: Vec<&str> = s.split(" > ").collect();
    let mut segs = Vec::new();
    for part in parts {
        if part.is_empty() { return None; }
        let bracket_pos = part.find('[');
        let key = if let Some(pos) = bracket_pos { part[..pos].to_string() } else { part.to_string() };
        let mut indices = Vec::new();
        let mut rest = if let Some(pos) = bracket_pos { &part[pos..] } else { "" };
        while !rest.is_empty() {
            if !rest.starts_with('[') { return None; }
            let end = rest.find(']')?;
            let num_str = &rest[1..end];
            if num_str.is_empty() { return None; }
            if !num_str.chars().all(|c| c.is_ascii_digit()) { return None; }
            let num: usize = num_str.parse().ok()?;
            indices.push(num);
            rest = &rest[end+1..];
        }
        segs.push(Segment { key, indices });
    }
    Some(segs)
}

fn get_by_additional_path(root: &Value, path_str: &str) -> Option<Value> {
    let segs = parse_additional_path(path_str)?;
    let mut cur = root;
    let mut arr_depth = 0usize;
    for seg in segs {
        if !seg.key.is_empty() {
            match cur {
                Value::Object(map) => {
                    if let Some(v) = map.get(&seg.key) {
                        cur = v;
                    } else { return None; }
                },
                _ => return None,
            }
            arr_depth = 0;
        }
        for idx_raw in seg.indices {
            match cur {
                Value::Array(arr) => {
                    let actual = if arr_depth==0 { idx_raw } else { if idx_raw==0 { return None; } else { idx_raw-1 } };
                    if actual >= arr.len() { return None; }
                    cur = &arr[actual];
                    arr_depth += 1;
                },
                _ => return None,
            }
        }
    }
    Some(cur.clone())
}

fn get_by_config_key(root: &Value, key: &str) -> Option<Value> {
    if let Value::Object(map) = root {
        if let Some(v) = map.get(key) {
            if !v.is_null() {
                return Some(v.clone());
            }
        }
    }
    if !key.contains('.') { return None; }
    let parts: Vec<&str> = key.split('.').collect();
    let mut cur = root;
    for part in parts {
        match cur {
            Value::Object(map) => {
                if let Some(v) = map.get(part) {
                    cur = v;
                } else { return None; }
            },
            _ => return None,
        }
    }
    if cur.is_null() { return None; }
    Some(cur.clone())
}

#[derive(Debug, Clone)]
struct FlatEntry {
    key: String,
    value: Value,
}

fn flatten_value(val: &Value, path: &str, depth: usize, out: &mut Vec<FlatEntry>) {
    match val {
        Value::Object(map) => {
            let mut keys: Vec<&String> = map.keys().collect();
            keys.sort();
            for k in keys {
                let child = map.get(k).unwrap();
                if child.is_null() { continue; }
                let new_path = if path.is_empty() { k.clone() } else { format!("{} > {}", path, k) };
                flatten_value(child, &new_path, 0, out);
            }
        },
        Value::Array(arr) => {
            for (i, elem) in arr.iter().enumerate() {
                if elem.is_null() { continue; }
                let idx = if depth==0 { i } else { i+1 };
                let elem_path = if path.is_empty() { format!("[{}]", idx) } else { format!("{}[{}]", path, idx) };
                match elem {
                    Value::Object(_) => {
                        flatten_value(elem, &elem_path, 0, out);
                    },
                    Value::Array(_) => {
                        flatten_value(elem, &elem_path, depth+1, out);
                    },
                    _ => {
                        out.push(FlatEntry { key: elem_path, value: elem.clone() });
                    }
                }
            }
        },
        Value::Null => {},
        _ => {
            out.push(FlatEntry { key: path.to_string(), value: val.clone() });
        }
    }
}

fn flatten_for_dump(root: &Value) -> Vec<FlatEntry> {
    let mut out = Vec::new();
    if let Value::Object(_) = root {
        flatten_value(root, "", 0, &mut out);
    }
    out.sort_by(|a,b| a.key.cmp(&b.key));
    out
}

fn flatten_selected(root: &Value, selector: &str) -> Vec<FlatEntry> {
    if let Some(v) = get_by_additional_path(root, selector) {
        let mut out = Vec::new();
        match &v {
            Value::Object(_) | Value::Array(_) => {
                flatten_value(&v, selector, 0, &mut out);
                out.sort_by(|a,b| a.key.cmp(&b.key));
                out
            },
            Value::Null => Vec::new(),
            _ => {
                vec![FlatEntry { key: selector.to_string(), value: v }]
            }
        }
    } else {
        Vec::new()
    }
}

fn parse_timestamp(raw: &Value) -> Option<String> {
    match raw {
        Value::Number(n) => {
            if let Some(u) = n.as_u64() {
                if u >= 1_000_000_000_000u64 {
                    let secs = (u / 1000) as i64;
                    let millis = (u % 1000) as u32;
                    let dt = Utc.timestamp_opt(secs, millis*1_000_000).single()?;
                    return Some(dt.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string());
                } else {
                    let secs = u as i64;
                    let dt = Utc.timestamp_opt(secs, 0).single()?;
                    return Some(dt.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string());
                }
            } else if let Some(i) = n.as_i64() {
                if i.abs() >= 1_000_000_000_000i64 {
                    let secs = i / 1000;
                    let millis = (i % 1000).abs() as u32;
                    let dt = Utc.timestamp_opt(secs, millis*1_000_000).single()?;
                    return Some(dt.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string());
                } else {
                    let dt = Utc.timestamp_opt(i, 0).single()?;
                    return Some(dt.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string());
                }
            }
            None
        },
        Value::String(s) => {
            if let Ok(u) = s.parse::<u64>() {
                let v = Value::Number(serde_json::Number::from(u));
                if let Some(p) = parse_timestamp(&v) { return Some(p); }
            }
            if let Ok(i) = s.parse::<i64>() {
                let v = Value::Number(serde_json::Number::from(i));
                if let Some(p) = parse_timestamp(&v) { return Some(p); }
            }
            Some(s.clone())
        },
        _ => None,
    }
}

// Template engine
#[derive(Debug, Clone)]
enum TemplateNode {
    Text(String),
    Variable(String),
    Helper { name: String, args: Vec<TemplateNode> },
    If { condition: String, then_branch: Vec<TemplateNode>, else_branch: Option<Vec<TemplateNode>> },
}

fn parse_template(s: &str) -> Result<Vec<TemplateNode>, String> {
    let mut nodes = Vec::new();
    let mut text_buf = String::new();
    let mut i = 0usize;
    while i < s.len() {
        if s[i..].starts_with("{{") {
            if !text_buf.is_empty() {
                nodes.push(TemplateNode::Text(text_buf.clone()));
                text_buf.clear();
            }
            let start = i+2;
            if let Some(end) = s[start..].find("}}") {
                let inner = s[start..start+end].trim();
                if inner.starts_with("#if") {
                    let cond = inner[3..].trim().to_string();
                    let after_if_start = start+end+2;
                    let (then_nodes, else_nodes, new_pos) = parse_if_block(&s[after_if_start..])?;
                    nodes.push(TemplateNode::If { condition: cond, then_branch: then_nodes, else_branch: else_nodes });
                    i = after_if_start + new_pos;
                    continue;
                } else if inner.starts_with("/if") {
                    return Err(format!("unexpected /if at position {}", i));
                } else if inner == "else" {
                    return Err(format!("unexpected else at position {}", i));
                } else {
                    let node = parse_helper_expr(inner)?;
                    nodes.push(node);
                    i = start + end + 2;
                    continue;
                }
            } else {
                return Err(format!("unclosed {{{{ at {}", i));
            }
        } else {
            let ch = s[i..].chars().next().unwrap();
            text_buf.push(ch);
            i += ch.len_utf8();
        }
    }
    if !text_buf.is_empty() {
        nodes.push(TemplateNode::Text(text_buf));
    }
    Ok(nodes)
}

fn parse_if_block(s: &str) -> Result<(Vec<TemplateNode>, Option<Vec<TemplateNode>>, usize), String> {
    let mut depth = 0usize;
    let mut i = 0usize;
    let mut else_start: Option<usize> = None;
    let mut else_end: Option<usize> = None;
    while i < s.len() {
        if s[i..].starts_with("{{") {
            let start = i+2;
            if let Some(end) = s[start..].find("}}") {
                let inner = s[start..start+end].trim();
                if inner.starts_with("#if") {
                    depth+=1;
                } else if inner.starts_with("/if") {
                    if depth==0 {
                        if let Some(es) = else_start {
                            let ee = else_end.unwrap();
                            let then_part = &s[..es];
                            let else_part = &s[ee..i];
                            let then_nodes = parse_template(then_part)?;
                            let else_nodes = parse_template(else_part)?;
                            return Ok((then_nodes, Some(else_nodes), start+end+2));
                        } else {
                            let then_content = &s[..i];
                            let then_nodes = parse_template(then_content)?;
                            return Ok((then_nodes, None, start+end+2));
                        }
                    } else {
                        depth-=1;
                    }
                } else if inner=="else" && depth==0 {
                    else_start = Some(i);
                    else_end = Some(start+end+2);
                }
                i = start+end+2;
                continue;
            } else {
                return Err("unclosed {{ in if block".into());
            }
        } else {
            let ch = s[i..].chars().next().unwrap();
            i += ch.len_utf8();
        }
    }
    Err("missing {{/if}}".into())
}

fn parse_helper_expr(s: &str) -> Result<TemplateNode, String> {
    let s = s.trim();
    if s.is_empty() { return Err("empty expression".into()); }
    let tokens = tokenize_helper(s)?;
    if tokens.is_empty() { return Err("no tokens".into()); }
    if tokens.len()==1 {
        let tok = &tokens[0];
        if tok.starts_with('(') && tok.ends_with(')') {
            let inner = tok[1..tok.len()-1].trim();
            return parse_helper_expr(inner);
        } else {
            return Ok(TemplateNode::Variable(tok.clone()));
        }
    } else {
        let name = tokens[0].clone();
        let mut args = Vec::new();
        for tok in tokens.iter().skip(1) {
            if tok.starts_with('(') && tok.ends_with(')') {
                let inner = &tok[1..tok.len()-1];
                let node = parse_helper_expr(inner)?;
                args.push(node);
            } else {
                args.push(TemplateNode::Variable(tok.clone()));
            }
        }
        Ok(TemplateNode::Helper { name, args })
    }
}

fn tokenize_helper(s: &str) -> Result<Vec<String>, String> {
    let mut tokens = Vec::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0usize;
    while i < chars.len() {
        while i < chars.len() && chars[i].is_whitespace() { i+=1; }
        if i>=chars.len() { break; }
        if chars[i]=='(' {
            let mut depth = 0usize;
            let mut j = i;
            while j < chars.len() {
                if chars[j]=='(' { depth+=1; }
                else if chars[j]==')' { depth-=1; if depth==0 { break; } }
                j+=1;
            }
            if depth!=0 { return Err("unmatched paren".into()); }
            let token: String = chars[i..=j].iter().collect();
            tokens.push(token);
            i = j+1;
        } else {
            let mut j = i;
            while j < chars.len() && !chars[j].is_whitespace() && chars[j]!='(' {
                j+=1;
            }
            let token: String = chars[i..j].iter().collect();
            tokens.push(token);
            i = j;
        }
    }
    Ok(tokens)
}

fn json_value_to_template_string(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        Value::Number(n) => n.to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Null => "".to_string(),
        Value::Array(arr) => {
            let mut parts = Vec::new();
            for elem in arr {
                parts.push(json_value_to_template_string(elem));
            }
            format!("[{}]", parts.join(", "))
        },
        Value::Object(_) => "[object]".to_string(),
    }
}

fn strip_ansi(s: &str) -> String {
    let re = Regex::new(r"\x1b\[[0-9;]*m").unwrap();
    re.replace_all(s, "").to_string()
}

fn truncate_ansi_aware(s: &str, size: usize) -> String {
    let mut out = String::new();
    let mut visible = 0usize;
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0usize;
    while i < chars.len() && visible < size {
        let c = chars[i];
        if c == '\x1b' {
            let mut esc_buf = String::new();
            esc_buf.push(c);
            i+=1;
            while i < chars.len() {
                let ec = chars[i];
                esc_buf.push(ec);
                i+=1;
                if ec == 'm' { break; }
            }
            out.push_str(&esc_buf);
        } else {
            out.push(c);
            visible+=1;
            i+=1;
        }
    }
    out
}

fn eval_template(nodes: &[TemplateNode], ctx: &HashMap<String, String>, json_root: &Value) -> Result<String, String> {
    let mut out = String::new();
    for node in nodes {
        out.push_str(&eval_node(node, ctx, json_root)?);
    }
    Ok(out)
}

fn eval_node(node: &TemplateNode, ctx: &HashMap<String, String>, json_root: &Value) -> Result<String, String> {
    match node {
        TemplateNode::Text(t) => Ok(t.clone()),
        TemplateNode::Variable(v) => {
            if v.chars().all(|c| c.is_ascii_digit()) {
                return Ok(v.clone());
            }
            if let Some(val) = ctx.get(v) {
                return Ok(val.clone());
            }
            if let Some(jv) = get_by_config_key(json_root, v) {
                return Ok(json_value_to_template_string(&jv));
            }
            if let Some(jv) = get_by_additional_path(json_root, v) {
                return Ok(json_value_to_template_string(&jv));
            }
            Ok("".to_string())
        },
        TemplateNode::Helper { name, args } => {
            let mut eval_args = Vec::new();
            for arg in args {
                eval_args.push(eval_node(arg, ctx, json_root)?);
            }
            match name.as_str() {
                "bold" => {
                    if eval_args.len()!=1 { return Err(format!("bold expects 1")); }
                    Ok(format!("\x1b[1m{}\x1b[0m", eval_args[0]))
                },
                "cyan" => {
                    if eval_args.len()!=1 { return Err(format!("cyan expects 1")); }
                    Ok(format!("\x1b[36m{}\x1b[0m", eval_args[0]))
                },
                "red" => {
                    if eval_args.len()!=1 { return Err(format!("red expects 1")); }
                    Ok(format!("\x1b[31m{}\x1b[0m", eval_args[0]))
                },
                "green" => {
                    if eval_args.len()!=1 { return Err(format!("green expects 1")); }
                    Ok(format!("\x1b[32m{}\x1b[0m", eval_args[0]))
                },
                "yellow" => {
                    if eval_args.len()!=1 { return Err(format!("yellow expects 1")); }
                    Ok(format!("\x1b[33m{}\x1b[0m", eval_args[0]))
                },
                "blue" => {
                    if eval_args.len()!=1 { return Err(format!("blue expects 1")); }
                    Ok(format!("\x1b[34m{}\x1b[0m", eval_args[0]))
                },
                "purple" => {
                    if eval_args.len()!=1 { return Err(format!("purple expects 1")); }
                    Ok(format!("\x1b[35m{}\x1b[0m", eval_args[0]))
                },
                "color_rgb" => {
                    if eval_args.len()!=4 { return Err(format!("color_rgb expects 4")); }
                    let r: u8 = eval_args[0].parse().map_err(|_| format!("Helper/Decorator color_rgb param with name r type mismatch for u64"))?;
                    let g: u8 = eval_args[1].parse().map_err(|_| format!("Helper/Decorator color_rgb param with name g type mismatch for u64"))?;
                    let b: u8 = eval_args[2].parse().map_err(|_| format!("Helper/Decorator color_rgb param with name b type mismatch for u64"))?;
                    Ok(format!("\x1b[38;2;{};{};{}m{}\x1b[0m", r,g,b, eval_args[3]))
                },
                "fixed_size" => {
                    if eval_args.len()!=2 { return Err(format!("fixed_size expects 2")); }
                    let size: usize = eval_args[0].parse().map_err(|_| format!("Helper/Decorator fixed_size param with name isize type mismatch for u64"))?;
                    let content = &eval_args[1];
                    let visible_len = strip_ansi(content).chars().count();
                    if visible_len > size {
                        Ok(truncate_ansi_aware(content, size))
                    } else {
                        let pad = size - visible_len;
                        Ok(format!("{}{}", " ".repeat(pad), content))
                    }
                },
                "min_size" => {
                    if eval_args.len()!=2 { return Err(format!("min_size expects 2")); }
                    let size: usize = eval_args[0].parse().map_err(|_| format!("Helper/Decorator min_size param with name isize type mismatch for u64"))?;
                    let content = &eval_args[1];
                    let visible_len = strip_ansi(content).chars().count();
                    if visible_len >= size {
                        Ok(content.clone())
                    } else {
                        let pad = size - visible_len;
                        Ok(format!("{}{}", " ".repeat(pad), content))
                    }
                },
                "uppercase" => {
                    if eval_args.len()!=1 { return Err(format!("uppercase expects 1")); }
                    Ok(eval_args[0].to_uppercase())
                },
                "level_style" => {
                    if eval_args.len()!=1 { return Err(format!("level_style expects 1")); }
                    let lvl = eval_args[0].clone();
                    let low = lvl.to_lowercase();
                    let color = match low.as_str() {
                        "trace" => "\x1b[1;36m",
                        "debug" => "\x1b[1;34m",
                        "info" => "\x1b[1;32m",
                        "warn" => "\x1b[1;33m",
                        "warning" => "\x1b[1;33m",
                        "error" => "\x1b[1;31m",
                        "err" => "\x1b[1;31m",
                        "fatal" => "\x1b[1;35m",
                        _ => "\x1b[1;35m",
                    };
                    Ok(format!("{}{}\x1b[0m", color, lvl))
                },
                _ => Err(format!("Helper not found {}", name)),
            }
        },
        TemplateNode::If { condition, then_branch, else_branch } => {
            let truthy = if let Some(v) = ctx.get(condition) {
                !v.is_empty()
            } else {
                if let Some(jv) = get_by_config_key(json_root, condition) {
                    match jv {
                        Value::Null => false,
                        Value::Bool(b) => b,
                        Value::String(s) => !s.is_empty(),
                        Value::Number(_) => true,
                        Value::Array(a) => !a.is_empty(),
                        Value::Object(o) => !o.is_empty(),
                    }
                } else if let Some(jv) = get_by_additional_path(json_root, condition) {
                    match jv {
                        Value::Null => false,
                        Value::Bool(b) => b,
                        Value::String(s) => !s.is_empty(),
                        Value::Number(_) => true,
                        Value::Array(a) => !a.is_empty(),
                        Value::Object(o) => !o.is_empty(),
                    }
                } else {
                    false
                }
            };
            if truthy {
                eval_template(then_branch, ctx, json_root)
            } else {
                if let Some(else_branch) = else_branch {
                    eval_template(else_branch, ctx, json_root)
                } else {
                    Ok("".to_string())
                }
            }
        },
    }
}

fn render_template(template_str: &str, ctx: &HashMap<String,String>, json_root: &Value) -> Result<String, String> {
    let nodes = parse_template(template_str).map_err(|e| {
        // Try to mimic original error format: Template invalid: TemplateError { reason: InvalidSyntax("..."), template_name: Some("main_line"), line_no: Some(1), column_no: Some(...), segment: Some("   0 | ...\n") }
        // For simplicity, we will return error that contains the template name
        // We need to detect which template is being rendered: main_line vs additional_value
        // We'll determine by caller? For now we will just return reason
        format!("{}", e)
    })?;
    eval_template(&nodes, ctx, json_root)
}

// Filter part
#[derive(Debug, Clone, PartialEq)]
enum FilterValue {
    Nil,
    Bool(bool),
    Number(f64),
    String(String),
    Table(HashMap<String, FilterValue>),
    Array(Vec<FilterValue>),
}

impl FilterValue {
    fn is_truthy(&self) -> bool {
        match self {
            FilterValue::Nil => false,
            FilterValue::Bool(b) => *b,
            _ => true,
        }
    }
}

fn sanitize_key(k: &str) -> String {
    let mut out = String::new();
    for ch in k.chars() {
        if ch.is_ascii_alphanumeric() || ch=='_' { out.push(ch); } else { out.push('_'); }
    }
    if out.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false) {
        out = format!("_{}", out);
    }
    if out.is_empty() { out = "_".into(); }
    out
}

fn json_to_filter_value_for_filter(v: &Value) -> FilterValue {
    match v {
        Value::Null => FilterValue::String("unsupported".to_string()),
        Value::Bool(b) => FilterValue::Bool(*b),
        Value::Number(n) => {
            if let Some(f) = n.as_f64() { FilterValue::Number(f) } else { FilterValue::String("unsupported".to_string()) }
        },
        Value::String(s) => FilterValue::String(s.clone()),
        Value::Object(map) => {
            let mut tbl = HashMap::new();
            for (k, child) in map {
                let sanitized = sanitize_key(k);
                tbl.insert(sanitized, json_to_filter_value_for_filter(child));
            }
            FilterValue::Table(tbl)
        },
        Value::Array(arr) => {
            let mut vec = Vec::new();
            for elem in arr {
                match elem {
                    Value::Number(_) | Value::String(_) | Value::Bool(_) => {
                        vec.push(json_to_filter_value_for_filter(elem));
                    },
                    _ => {
                        vec.push(FilterValue::String("unsupported".to_string()));
                    }
                }
            }
            FilterValue::Array(vec)
        },
    }
}

fn filter_value_to_lua(v: &FilterValue) -> String {
    match v {
        FilterValue::String(s) => {
            if s=="unsupported" {
                "\"unsupported\"".to_string()
            } else {
                let esc = s.replace('\\',"\\\\").replace('"',"\\\"").replace('\n',"\\n").replace('\r',"\\r");
                format!("\"{}\"", esc)
            }
        },
        FilterValue::Bool(b) => b.to_string(),
        FilterValue::Number(n) => {
            if n.fract()==0.0 { format!("{}", *n as i64) } else { n.to_string() }
        },
        FilterValue::Nil => "\"unsupported\"".to_string(),
        FilterValue::Table(tbl) => {
            let mut keys: Vec<&String> = tbl.keys().collect();
            keys.sort();
            let mut parts = Vec::new();
            for k in keys {
                parts.push(format!("{} = {}", k, filter_value_to_lua(tbl.get(k).unwrap())));
            }
            format!("{{{}}}", parts.join(","))
        },
        FilterValue::Array(arr) => {
            let mut parts = Vec::new();
            for e in arr {
                parts.push(filter_value_to_lua(e));
            }
            format!("{{{}}}", parts.join(","))
        },
    }
}

#[derive(Debug, Clone, PartialEq)]
enum BinOp { Eq, NotEq, Lt, Gt, Le, Ge, And, Or, Add, Sub, Mul, Div, Mod, Concat }
#[derive(Debug, Clone, PartialEq)]
enum UnOp { Not, Neg }
#[derive(Debug, Clone)]
enum Expr {
    Nil,
    Bool(bool),
    Number(f64),
    Str(String),
    Var(String),
    FieldAccess { base: Box<Expr>, field: String },
    Index { base: Box<Expr>, index: Box<Expr> },
    Unary { op: UnOp, expr: Box<Expr> },
    Binary { op: BinOp, left: Box<Expr>, right: Box<Expr> },
    Call { func: String, args: Vec<Expr> },
}

struct FilterParser {
    input: Vec<char>,
    pos: usize,
}

impl FilterParser {
    fn new(s: &str) -> Self { Self { input: s.chars().collect(), pos:0 } }
    fn peek(&self) -> Option<char> { self.input.get(self.pos).cloned() }
    fn peek_next(&self) -> Option<char> { self.input.get(self.pos+1).cloned() }
    fn consume(&mut self) -> Option<char> { if self.pos < self.input.len() { let c=self.input[self.pos]; self.pos+=1; Some(c) } else { None } }
    fn skip_ws(&mut self) { while let Some(c)=self.peek() { if c.is_whitespace() { self.pos+=1; } else { break; } } }
    fn expect(&mut self, ch: char) -> Result<(), String> { self.skip_ws(); if self.peek()==Some(ch) { self.pos+=1; Ok(()) } else { Err(format!("expected '{}'", ch)) } }
    fn parse(&mut self) -> Result<Expr, String> {
        self.skip_ws();
        let e = self.parse_or()?;
        self.skip_ws();
        if self.pos < self.input.len() {
            let remaining: String = self.input[self.pos..].iter().collect();
            return Err(format!("unexpected symbol near '{}'", remaining.chars().next().unwrap_or('?')));
        }
        Ok(e)
    }
    fn parse_or(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_and()?;
        loop {
            self.skip_ws();
            if self.match_word("or") {
                let right = self.parse_and()?;
                left = Expr::Binary { op: BinOp::Or, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_and(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_comparison()?;
        loop {
            self.skip_ws();
            if self.match_word("and") {
                let right = self.parse_comparison()?;
                left = Expr::Binary { op: BinOp::And, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_comparison(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_concat()?;
        loop {
            self.skip_ws();
            let op = if self.match_str("==") { Some(BinOp::Eq) }
            else if self.match_str("~=") { Some(BinOp::NotEq) }
            else if self.match_str("<=") { Some(BinOp::Le) }
            else if self.match_str(">=") { Some(BinOp::Ge) }
            else if self.match_str("<") { Some(BinOp::Lt) }
            else if self.match_str(">") { Some(BinOp::Gt) }
            else { None };
            if let Some(op) = op {
                let right = self.parse_concat()?;
                left = Expr::Binary { op, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_concat(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_add_sub()?;
        loop {
            self.skip_ws();
            if self.match_str("..") {
                let right = self.parse_add_sub()?;
                left = Expr::Binary { op: BinOp::Concat, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_add_sub(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_mul_div()?;
        loop {
            self.skip_ws();
            if self.match_str("+") {
                if self.peek()==Some('=') { break; }
                let right = self.parse_mul_div()?;
                left = Expr::Binary { op: BinOp::Add, left: Box::new(left), right: Box::new(right) };
            } else if self.match_str("-") {
                if self.peek()==Some('=') { break; }
                let right = self.parse_mul_div()?;
                left = Expr::Binary { op: BinOp::Sub, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_mul_div(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_unary()?;
        loop {
            self.skip_ws();
            if self.match_str("*") {
                let right = self.parse_unary()?;
                left = Expr::Binary { op: BinOp::Mul, left: Box::new(left), right: Box::new(right) };
            } else if self.match_str("/") {
                let right = self.parse_unary()?;
                left = Expr::Binary { op: BinOp::Div, left: Box::new(left), right: Box::new(right) };
            } else if self.match_str("%") {
                let right = self.parse_unary()?;
                left = Expr::Binary { op: BinOp::Mod, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_unary(&mut self) -> Result<Expr, String> {
        self.skip_ws();
        if self.match_word("not") {
            let e = self.parse_unary()?;
            return Ok(Expr::Unary { op: UnOp::Not, expr: Box::new(e) });
        }
        if self.match_str("-") {
            let e = self.parse_unary()?;
            return Ok(Expr::Unary { op: UnOp::Neg, expr: Box::new(e) });
        }
        self.parse_primary()
    }
    fn parse_primary(&mut self) -> Result<Expr, String> {
        self.skip_ws();
        let c = self.peek().ok_or("unexpected eof".to_string())?;
        if c=='(' {
            self.consume();
            let e = self.parse_or()?;
            self.skip_ws();
            self.expect(')')?;
            return self.parse_postfix(e);
        } else if c=='"' || c=='\'' {
            let s = self.parse_string()?;
            return self.parse_postfix(Expr::Str(s));
        } else if c.is_ascii_digit() {
            let num = self.parse_number()?;
            return self.parse_postfix(Expr::Number(num));
        } else if is_ident_start(c) {
            let ident = self.parse_ident()?;
            if ident=="nil" {
                return self.parse_postfix(Expr::Nil);
            } else if ident=="true" {
                return self.parse_postfix(Expr::Bool(true));
            } else if ident=="false" {
                return self.parse_postfix(Expr::Bool(false));
            } else if ident=="return" {
                return Err(format!("<eof> expected near 'return'"));
            } else {
                let base = Expr::Var(ident);
                let expr = self.parse_postfix(base)?;
                self.skip_ws();
                if self.peek()==Some('(') {
                    return self.parse_call(expr);
                } else {
                    return Ok(expr);
                }
            }
        } else {
            return Err(format!("unexpected symbol near '{}'", c));
        }
    }
    fn parse_postfix(&mut self, mut base: Expr) -> Result<Expr, String> {
        loop {
            self.skip_ws();
            if self.peek()==Some('.') {
                self.consume();
                let field = self.parse_ident().map_err(|_| format!("unexpected symbol near '.'"))?;
                base = Expr::FieldAccess { base: Box::new(base), field };
            } else if self.peek()==Some('[') {
                self.consume();
                let idx_expr = self.parse_or()?;
                self.skip_ws();
                self.expect(']')?;
                base = Expr::Index { base: Box::new(base), index: Box::new(idx_expr) };
            } else { break; }
        }
        Ok(base)
    }
    fn parse_call(&mut self, func_expr: Expr) -> Result<Expr, String> {
        let func_name = match &func_expr {
            Expr::Var(v) => v.clone(),
            Expr::FieldAccess { base, field } => {
                let mut parts = Vec::new();
                let mut cur = &func_expr;
                loop {
                    match cur {
                        Expr::FieldAccess { base, field } => {
                            parts.push(field.clone());
                            cur = base;
                        },
                        Expr::Var(v) => {
                            parts.push(v.clone());
                            break;
                        },
                        _ => return Err("invalid func name".into()),
                    }
                }
                parts.reverse();
                parts.join(".")
            },
            _ => return Err("invalid function expr".into()),
        };
        self.skip_ws();
        self.expect('(')?;
        let mut args = Vec::new();
        loop {
            self.skip_ws();
            if self.peek()==Some(')') {
                self.consume();
                break;
            }
            let arg = self.parse_or()?;
            args.push(arg);
            self.skip_ws();
            if self.peek()==Some(',') {
                self.consume();
                continue;
            } else if self.peek()==Some(')') {
                continue;
            } else {
                return Err(format!("expected , or )"));
            }
        }
        let call_expr = Expr::Call { func: func_name, args };
        self.parse_postfix(call_expr)
    }
    fn parse_string(&mut self) -> Result<String, String> {
        let quote = self.consume().unwrap();
        let mut s = String::new();
        while let Some(c) = self.consume() {
            if c==quote { return Ok(s); }
            else if c=='\\' {
                if let Some(esc) = self.consume() {
                    match esc {
                        'n' => s.push('\n'),
                        'r' => s.push('\r'),
                        't' => s.push('\t'),
                        '\\' => s.push('\\'),
                        '"' => s.push('"'),
                        '\'' => s.push('\''),
                        _ => { s.push('\\'); s.push(esc); }
                    }
                } else { return Err("unterminated escape".into()); }
            } else { s.push(c); }
        }
        Err("unterminated string".into())
    }
    fn parse_number(&mut self) -> Result<f64, String> {
        let mut num_str = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c=='.' {
                num_str.push(c);
                self.consume();
            } else { break; }
        }
        if num_str.is_empty() { return Err(" expected number".into()); }
        num_str.parse::<f64>().map_err(|_| format!("invalid number {}", num_str))
    }
    fn parse_ident(&mut self) -> Result<String, String> {
        self.skip_ws();
        let mut ident = String::new();
        if let Some(c) = self.peek() {
            if !is_ident_start(c) { return Err(format!("unexpected symbol near '{}'", c)); }
        } else { return Err("<eof> expected".into()); }
        while let Some(c) = self.peek() {
            if is_ident_continue(c) {
                ident.push(c);
                self.consume();
            } else { break; }
        }
        if ident.is_empty() { return Err("expected identifier".into()); }
        Ok(ident)
    }
    fn match_word(&mut self, word: &str) -> bool {
        self.skip_ws();
        let len = word.len();
        if self.pos + len > self.input.len() { return false; }
        let substr: String = self.input[self.pos..self.pos+len].iter().collect();
        if substr != word { return false; }
        if self.pos+len < self.input.len() {
            if is_ident_continue(self.input[self.pos+len]) { return false; }
        }
        self.pos+=len;
        true
    }
    fn match_str(&mut self, s: &str) -> bool {
        self.skip_ws();
        let len = s.len();
        if self.pos+len > self.input.len() { return false; }
        let substr: String = self.input[self.pos..self.pos+len].iter().collect();
        if substr==s {
            if s=="=" {
                if self.pos+len < self.input.len() && self.input[self.pos+len]=='=' { return false; }
            }
            if s=="<" || s==">" {
                if self.pos+len < self.input.len() {
                    let next = self.input[self.pos+len];
                    if next=='=' { return false; }
                }
            }
            if s=="-" {
                if self.pos+len < self.input.len() {
                    let next = self.input[self.pos+len];
                    if next=='-' { return false; }
                }
            }
            self.pos+=len;
            true
        } else { false }
    }
}

fn is_ident_start(c: char) -> bool { c.is_ascii_alphabetic() || c=='_' }
fn is_ident_continue(c: char) -> bool { c.is_ascii_alphanumeric() || c=='_' }

fn eval_filter_expr(expr: &Expr, env: &HashMap<String, FilterValue>) -> Result<FilterValue, String> {
    match expr {
        Expr::Nil => Ok(FilterValue::Nil),
        Expr::Bool(b) => Ok(FilterValue::Bool(*b)),
        Expr::Number(n) => Ok(FilterValue::Number(*n)),
        Expr::Str(s) => Ok(FilterValue::String(s.clone())),
        Expr::Var(name) => {
            Ok(env.get(name).cloned().unwrap_or(FilterValue::Nil))
        },
        Expr::FieldAccess { base, field } => {
            let base_val = eval_filter_expr(base, env)?;
            match base_val {
                FilterValue::Table(tbl) => Ok(tbl.get(field).cloned().unwrap_or(FilterValue::Nil)),
                _ => Ok(FilterValue::Nil),
            }
        },
        Expr::Index { base, index } => {
            let base_val = eval_filter_expr(base, env)?;
            let idx_val = eval_filter_expr(index, env)?;
            match (base_val, idx_val) {
                (FilterValue::Array(arr), FilterValue::Number(n)) => {
                    let idx = n as usize;
                    if idx==0 { Ok(FilterValue::Nil) } else if idx<=arr.len() { Ok(arr[idx-1].clone()) } else { Ok(FilterValue::Nil) }
                },
                (FilterValue::Table(tbl), FilterValue::String(s)) => Ok(tbl.get(&s).cloned().unwrap_or(FilterValue::Nil)),
                (FilterValue::Table(tbl), FilterValue::Number(n)) => {
                    let key = (n as i64).to_string();
                    Ok(tbl.get(&key).cloned().unwrap_or(FilterValue::Nil))
                },
                _ => Ok(FilterValue::Nil),
            }
        },
        Expr::Unary { op, expr } => {
            let v = eval_filter_expr(expr, env)?;
            match op {
                UnOp::Not => Ok(FilterValue::Bool(!v.is_truthy())),
                UnOp::Neg => {
                    if let FilterValue::Number(n) = v { Ok(FilterValue::Number(-n)) } else { Err(format!("attempt to perform arithmetic on a {:?}", v)) }
                }
            }
        },
        Expr::Binary { op, left, right } => {
            match op {
                BinOp::And => {
                    let l = eval_filter_expr(left, env)?;
                    if !l.is_truthy() { return Ok(l); }
                    eval_filter_expr(right, env)
                },
                BinOp::Or => {
                    let l = eval_filter_expr(left, env)?;
                    if l.is_truthy() { return Ok(l); }
                    eval_filter_expr(right, env)
                },
                _ => {
                    let l = eval_filter_expr(left, env)?;
                    let r = eval_filter_expr(right, env)?;
                    eval_binary(op, l, r)
                }
            }
        },
        Expr::Call { func, args } => {
            if func=="string.find" {
                if args.len()<2 { return Err("string.find needs 2 args".into()); }
                let s_val = eval_filter_expr(&args[0], env)?;
                let pat_val = eval_filter_expr(&args[1], env)?;
                let s = match s_val {
                    FilterValue::String(s) => s,
                    FilterValue::Nil => return Err(format!("bad argument #1 to 'find' (string expected, got nil)\nstack traceback:\n\t[C]: in ?\n\t[C]: in function 'string.find'\n\tsrc/filter.rs:23:1: in main chunk")),
                    _ => return Err(format!("bad argument #1 to 'find' (string expected, got {:?})", s_val)),
                };
                let pat = match pat_val {
                    FilterValue::String(p) => p,
                    _ => return Err("bad arg #2".into()),
                };
                let found = if let Ok(re) = Regex::new(&pat) {
                    re.find(&s).is_some()
                } else {
                    s.contains(&pat)
                };
                if found { Ok(FilterValue::Number(1.0)) } else { Ok(FilterValue::Nil) }
            } else {
                Err(format!("unknown function {}", func))
            }
        }
    }
}

fn eval_binary(op: &BinOp, left: FilterValue, right: FilterValue) -> Result<FilterValue, String> {
    match op {
        BinOp::Eq => Ok(FilterValue::Bool(left==right)),
        BinOp::NotEq => Ok(FilterValue::Bool(left!=right)),
        BinOp::Lt | BinOp::Gt | BinOp::Le | BinOp::Ge => {
            match (left.clone(), right.clone()) {
                (FilterValue::Number(a), FilterValue::Number(b)) => {
                    let res = match op {
                        BinOp::Lt => a<b,
                        BinOp::Gt => a>b,
                        BinOp::Le => a<=b,
                        BinOp::Ge => a>=b,
                        _ => false,
                    };
                    Ok(FilterValue::Bool(res))
                },
                (FilterValue::String(a), FilterValue::String(b)) => {
                    let res = match op {
                        BinOp::Lt => a<b,
                        BinOp::Gt => a>b,
                        BinOp::Le => a<=b,
                        BinOp::Ge => a>=b,
                        _ => false,
                    };
                    Ok(FilterValue::Bool(res))
                },
                (FilterValue::Nil, FilterValue::Table(_)) | (FilterValue::Table(_), FilterValue::Nil) => {
                    Err("attempt to compare nil with table".to_string())
                },
                _ => Err(format!("attempt to compare {:?} with {:?}", left, right)),
            }
        },
        BinOp::Add => match (left, right) {
            (FilterValue::Number(a), FilterValue::Number(b)) => Ok(FilterValue::Number(a+b)),
            _ => Err("add non-numbers".into()),
        },
        BinOp::Sub => match (left, right) {
            (FilterValue::Number(a), FilterValue::Number(b)) => Ok(FilterValue::Number(a-b)),
            _ => Err("sub".into()),
        },
        BinOp::Mul => match (left, right) {
            (FilterValue::Number(a), FilterValue::Number(b)) => Ok(FilterValue::Number(a*b)),
            _ => Err("mul".into()),
        },
        BinOp::Div => match (left, right) {
            (FilterValue::Number(a), FilterValue::Number(b)) => Ok(FilterValue::Number(a/b)),
            _ => Err("div".into()),
        },
        BinOp::Mod => match (left, right) {
            (FilterValue::Number(a), FilterValue::Number(b)) => Ok(FilterValue::Number(a % b)),
            _ => Err("mod".into()),
        },
        BinOp::Concat => {
            let a_str = match left {
                FilterValue::String(s) => s,
                FilterValue::Number(n) => n.to_string(),
                _ => return Err("concat".into()),
            };
            let b_str = match right {
                FilterValue::String(s) => s,
                FilterValue::Number(n) => n.to_string(),
                _ => return Err("concat".into()),
            };
            Ok(FilterValue::String(format!("{}{}", a_str, b_str)))
        },
        _ => Err("unsupported op".into()),
    }
}

fn render_value_colored(val: &Value) -> String {
    match val {
        Value::Null => format!("\x1b[1mnull\x1b[0m"),
        Value::Bool(b) => {
            if *b { format!("\x1b[1;32mtrue\x1b[0m") } else { format!("\x1b[1;31mfalse\x1b[0m") }
        },
        Value::Number(n) => format!("\x1b[1;36m{}\x1b[0m", n),
        Value::String(s) => format!("\x1b[1;33m{}\x1b[0m", s),
        Value::Array(arr) => {
            let mut parts = Vec::new();
            for elem in arr {
                parts.push(render_value_colored(elem));
            }
            format!("\x1b[2m[\x1b[0m{}\x1b[2m]\x1b[0m", parts.join("\x1b[2m, \x1b[0m"))
        },
        Value::Object(map) => {
            let mut keys: Vec<&String> = map.keys().collect();
            keys.sort();
            let mut parts = Vec::new();
            for k in keys {
                let v = map.get(k).unwrap();
                let k_colored = format!("\x1b[35m{}\x1b[0m", k);
                let v_colored = render_value_colored(v);
                parts.push(format!("{}: {}", k_colored, v_colored));
            }
            format!("\x1b[2m{{\x1b[0m{}\x1b[2m}}\x1b[0m", parts.join("\x1b[2m, \x1b[0m"))
        }
    }
}

fn main() {
    let cmd = Command::new("fblog")
        .version("4.17.0")
        .about("json log viewer")
        .arg(Arg::new("input").default_value("-"))
        .arg(Arg::new("additional-value").short('a').long("additional-value").action(ArgAction::Append).value_name("additional-value"))
        .arg(Arg::new("config-file").long("config-file").value_name("config-file"))
        .arg(Arg::new("message-key").short('m').long("message-key").action(ArgAction::Append).value_name("message-key"))
        .arg(Arg::new("print-lua").long("print-lua").action(ArgAction::SetTrue))
        .arg(Arg::new("time-key").short('t').long("time-key").action(ArgAction::Append).value_name("time-key"))
        .arg(Arg::new("level-key").short('l').long("level-key").action(ArgAction::Append).value_name("level-key"))
        .arg(Arg::new("map-level").long("map-level").action(ArgAction::Append).value_name("from=to"))
        .arg(Arg::new("dump-all").short('d').long("dump-all").action(ArgAction::SetTrue))
        .arg(Arg::new("excluded-value").short('x').long("excluded-value").action(ArgAction::Append).value_name("excluded-value"))
        .arg(Arg::new("with-prefix").short('p').long("with-prefix").action(ArgAction::SetTrue))
        .arg(Arg::new("filter").short('f').long("filter").value_name("filter"))
        .arg(Arg::new("no-implicit-filter-return-statement").long("no-implicit-filter-return-statement").action(ArgAction::SetTrue))
        .arg(Arg::new("main-line-format").long("main-line-format").value_name("main-line-format"))
        .arg(Arg::new("additional-value-format").long("additional-value-format").value_name("additional-value-format"))
        .arg(Arg::new("substitute").short('s').long("substitute").action(ArgAction::SetTrue))
        .arg(Arg::new("context-key").short('c').long("context-key").value_name("context-key"))
        .arg(Arg::new("placeholder-format").short('F').long("placeholder-format").value_name("placeholder-format"))
        ;
    let matches = cmd.get_matches();
    let input = matches.get_one::<String>("input").unwrap().clone();
    let additional_values: Vec<String> = matches.get_many::<String>("additional-value").map(|v| v.cloned().collect()).unwrap_or_default();
    let excluded_values: Vec<String> = matches.get_many::<String>("excluded-value").map(|v| v.cloned().collect()).unwrap_or_default();
    let message_keys_cli: Vec<String> = matches.get_many::<String>("message-key").map(|v| v.cloned().collect()).unwrap_or_default();
    let time_keys_cli: Vec<String> = matches.get_many::<String>("time-key").map(|v| v.cloned().collect()).unwrap_or_default();
    let level_keys_cli: Vec<String> = matches.get_many::<String>("level-key").map(|v| v.cloned().collect()).unwrap_or_default();
    let map_level_raw: Vec<String> = matches.get_many::<String>("map-level").map(|v| v.cloned().collect()).unwrap_or_default();
    let dump_all = matches.get_flag("dump-all") || !excluded_values.is_empty();
    let with_prefix = matches.get_flag("with-prefix");
    let print_lua = matches.get_flag("print-lua");
    let filter_opt = matches.get_one::<String>("filter").cloned();
    let no_implicit = matches.get_flag("no-implicit-filter-return-statement");
    let main_line_format_cli = matches.get_one::<String>("main-line-format").cloned();
    let additional_value_format_cli = matches.get_one::<String>("additional-value-format").cloned();
    let substitute = matches.get_flag("substitute");
    let context_key = matches.get_one::<String>("context-key").cloned();
    let placeholder_format = matches.get_one::<String>("placeholder-format").cloned().unwrap_or_else(|| "{key}".to_string());
    let config_file_opt = matches.get_one::<String>("config-file").cloned();

    if !additional_values.is_empty() && !excluded_values.is_empty() {
        eprintln!("error: the argument '--additional-value <additional-value>' cannot be used with '--excluded-value <excluded-value>'");
        eprintln!();
        eprintln!("Usage: fblog --additional-value <additional-value> [INPUT]");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }

    let mut cfg = load_config(config_file_opt);

    for s in map_level_raw {
        if let Ok((f,t)) = parse_map_level(&s) {
            cfg.level_map.insert(f, t);
        }
    }

    let mut mk = message_keys_cli.clone();
    mk.extend(cfg.message_keys.clone());
    cfg.message_keys = mk;
    let mut tk = time_keys_cli.clone();
    tk.extend(cfg.time_keys.clone());
    cfg.time_keys = tk;
    let mut lk = level_keys_cli.clone();
    lk.extend(cfg.level_keys.clone());
    cfg.level_keys = lk;

    if let Some(f) = main_line_format_cli { cfg.main_line_format = f; }
    if let Some(f) = additional_value_format_cli { cfg.additional_value_format = f; }

    let mut filter_expr_opt: Option<String> = None;
    if let Some(f) = filter_opt {
        let expr = if no_implicit { f.clone() } else { format!("return {}", f) };
        filter_expr_opt = Some(expr);
    }

    // Read input lines preserving invalid utf8 detection
    let mut lines: Vec<Result<String, ()>> = Vec::new();
    if input=="-" {
        let mut buf = Vec::new();
        io::stdin().read_to_end(&mut buf).unwrap();
        let mut start = 0usize;
        for i in 0..buf.len() {
            if buf[i]==b'\n' {
                let slice = &buf[start..i];
                let slice = if !slice.is_empty() && slice.last()==Some(&b'\r') { &slice[..slice.len()-1] } else { slice };
                match std::str::from_utf8(slice) {
                    Ok(s) => lines.push(Ok(s.to_string())),
                    Err(_) => lines.push(Err(())),
                }
                start = i+1;
            }
        }
        if start < buf.len() {
            let slice = &buf[start..];
            let slice = if !slice.is_empty() && slice.last()==Some(&b'\r') { &slice[..slice.len()-1] } else { slice };
            match std::str::from_utf8(slice) {
                Ok(s) => lines.push(Ok(s.to_string())),
                Err(_) => lines.push(Err(())),
            }
        }
    } else {
        let data = match std::fs::read(&input) {
            Ok(d) => d,
            Err(_) => {
                panic!("Can't open file: {}", input);
            }
        };
        let mut start = 0usize;
        for i in 0..data.len() {
            if data[i]==b'\n' {
                let slice = &data[start..i];
                let slice = if !slice.is_empty() && slice.last()==Some(&b'\r') { &slice[..slice.len()-1] } else { slice };
                match std::str::from_utf8(slice) {
                    Ok(s) => lines.push(Ok(s.to_string())),
                    Err(_) => lines.push(Err(())),
                }
                start = i+1;
            }
        }
        if start < data.len() {
            let slice = &data[start..];
            let slice = if !slice.is_empty() && slice.last()==Some(&b'\r') { &slice[..slice.len()-1] } else { slice };
            match std::str::from_utf8(slice) {
                Ok(s) => lines.push(Ok(s.to_string())),
                Err(_) => lines.push(Err(())),
            }
        }
    }

    for line_res in lines {
        if line_res.is_err() {
            println!("\x1b[1;31m??? >\x1b[0m Could not read line: stream did not contain valid UTF-8");
            continue;
        }
        let line = line_res.unwrap();

        let (prefix_opt, json_str) = if with_prefix {
            if let Some(pos) = line.find('{') {
                let prefix_raw = &line[..pos];
                let trimmed = prefix_raw.trim().to_string();
                (Some(trimmed), line[pos..].to_string())
            } else {
                (None, line.clone())
            }
        } else {
            (None, line.clone())
        };

        let json_val_res: Result<Value, _> = serde_json::from_str(&json_str);
        let is_valid = match &json_val_res {
            Ok(v) => v.is_object(),
            Err(_) => false,
        };

        if !is_valid {
            println!("\x1b[1;38;2;255;135;22m??? >\x1b[0m {}", line);
            continue;
        }

        let json_obj = json_val_res.unwrap();

        // message
        let mut fblog_message_str = String::new();
        for k in &cfg.message_keys {
            let mut v_opt = get_by_config_key(&json_obj, k);
            if v_opt.is_none() {
                v_opt = get_by_additional_path(&json_obj, k);
            }
            if let Some(v) = v_opt {
                match v {
                    Value::String(s) => { fblog_message_str = s; break; },
                    Value::Number(n) => { fblog_message_str = n.to_string(); break; },
                    Value::Bool(b) => { fblog_message_str = b.to_string(); break; },
                    _ => continue,
                }
            }
        }

        // level
        let mut fblog_level_raw_str: Option<String> = None;
        for k in &cfg.level_keys {
            let mut v_opt = get_by_config_key(&json_obj, k);
            if v_opt.is_none() {
                v_opt = get_by_additional_path(&json_obj, k);
            }
            if let Some(v) = v_opt {
                match v {
                    Value::String(s) => { fblog_level_raw_str = Some(s); break; },
                    Value::Number(n) => { fblog_level_raw_str = Some(n.to_string()); break; },
                    _ => continue,
                }
            }
        }
        let mut fblog_level_display = fblog_level_raw_str.clone().unwrap_or_else(|| "unknown".to_string());
        if let Some(raw) = &fblog_level_raw_str {
            if let Some(mapped) = cfg.level_map.get(raw) {
                fblog_level_display = mapped.clone();
            }
        }

        // timestamp
        let mut fblog_timestamp_str = String::new();
        for k in &cfg.time_keys {
            let mut v_opt = get_by_config_key(&json_obj, k);
            if v_opt.is_none() {
                v_opt = get_by_additional_path(&json_obj, k);
            }
            if let Some(v) = v_opt {
                if let Some(p) = parse_timestamp(&v) {
                    fblog_timestamp_str = p;
                } else {
                    match v {
                        Value::String(s) => { fblog_timestamp_str = s; },
                        Value::Number(n) => { fblog_timestamp_str = n.to_string(); },
                        _ => {}
                    }
                }
                break;
            }
        }

        let fblog_prefix = prefix_opt.clone().unwrap_or_else(|| "".to_string());

        // filter env
        let mut filter_env: HashMap<String, FilterValue> = HashMap::new();
        if let Value::Object(map) = &json_obj {
            for (k,v) in map {
                let sanitized = sanitize_key(k);
                let fv = json_to_filter_value_for_filter(v);
                filter_env.insert(sanitized, fv);
            }
        }

        if print_lua {
            if filter_expr_opt.is_some() {
                let mut keys: Vec<&String> = filter_env.keys().collect();
                keys.sort();
                for k in keys {
                    let v = filter_env.get(k).unwrap();
                    println!("{} = {}", k, filter_value_to_lua(v));
                }
            }
        }

        let mut filter_pass = true;
        if let Some(filter_str) = &filter_expr_opt {
            let expr_to_parse = if filter_str.starts_with("return ") {
                filter_str["return ".len()..].trim()
            } else {
                filter_str.trim()
            };
            let mut parser = FilterParser::new(expr_to_parse);
            match parser.parse() {
                Ok(expr) => {
                    match eval_filter_expr(&expr, &filter_env) {
                        Ok(val) => {
                            filter_pass = val.is_truthy();
                        },
                        Err(e) => {
                            eprintln!("\x1b[31mFailed to apply filter expression\x1b[0m: 'RuntimeError(\"src/filter.rs:23:1: {}\")'", e);
                            filter_pass = false;
                        }
                    }
                },
                Err(e) => {
                    if e.contains("<eof> expected near 'return'") {
                        eprintln!("\x1b[31mFailed to apply filter expression\x1b[0m: 'SyntaxError {{ message: \"src/filter.rs:23:1: <eof> expected near 'return'\", incomplete_input: false }}'");
                    } else if e.contains("unexpected symbol near 'for'") || e.contains("for") && e.contains("unexpected") {
                        // generic for case: we already have generic message that contains the problematic symbol
                        eprintln!("\x1b[31mFailed to apply filter expression\x1b[0m: 'SyntaxError {{ message: \"src/filter.rs:23:1: unexpected symbol near 'for'\", incomplete_input: false }}'");
                    } else {
                        eprintln!("\x1b[31mFailed to apply filter expression\x1b[0m: 'SyntaxError {{ message: \"src/filter.rs:23:1: {}\", incomplete_input: false }}'", e);
                    }
                    filter_pass = false;
                }
            }
        }

        if !filter_pass { continue; }

        // substitute
        let mut final_message = fblog_message_str.clone();
        if substitute {
            if let Some(ctx_key) = &context_key {
                let mut ctx_val_opt: Option<Value> = None;
                if let Some(v) = get_by_config_key(&json_obj, ctx_key) {
                    ctx_val_opt = Some(v);
                } else if let Some(v) = get_by_additional_path(&json_obj, ctx_key) {
                    ctx_val_opt = Some(v);
                }
                if let Some(ctx_val) = ctx_val_opt {
                    let mut repls: Vec<(String, String)> = Vec::new();
                    match ctx_val {
                        Value::Object(map) => {
                            for (k,v) in map {
                                let ph = placeholder_format.replace("key", &k);
                                repls.push((ph, render_value_colored(&v)));
                            }
                        },
                        Value::Array(arr) => {
                            for (i,v) in arr.iter().enumerate() {
                                let ph = placeholder_format.replace("key", &i.to_string());
                                repls.push((ph, render_value_colored(v)));
                            }
                        },
                        _ => {}
                    }
                    let parts: Vec<&str> = placeholder_format.split("key").collect();
                    let (pfx, sfx) = if parts.len()>=2 { (parts[0], parts[1]) } else { ("", "") };
                    let mut result = String::new();
                    let mut last = 0usize;
                    let msg = final_message.clone();
                    let mut search_start = 0usize;
                    while search_start < msg.len() {
                        if let Some(start) = msg[search_start..].find(pfx) {
                            let abs_start = search_start + start;
                            let after = abs_start + pfx.len();
                            if let Some(end) = msg[after..].find(sfx) {
                                let abs_end = after + end;
                                let key_inside = &msg[after..abs_end];
                                let full_ph = format!("{}{}{}", pfx, key_inside, sfx);
                                let mut rep_opt: Option<String> = None;
                                for (ph, rep) in &repls {
                                    if ph == &full_ph {
                                        rep_opt = Some(rep.clone());
                                        break;
                                    }
                                }
                                result.push_str(&msg[last..abs_start]);
                                if let Some(rep) = rep_opt {
                                    result.push_str(&rep);
                                } else {
                                    result.push_str(&format!("\x1b[2m{}\x1b[0m\x1b[1;31m{}\x1b[0m\x1b[2m{}\x1b[0m", pfx, key_inside, sfx));
                                }
                                last = abs_end + sfx.len();
                                search_start = last;
                                continue;
                            } else { break; }
                        } else { break; }
                    }
                    result.push_str(&msg[last..]);
                    final_message = result;
                }
            }
        }

        let mut tmpl_ctx: HashMap<String, String> = HashMap::new();
        tmpl_ctx.insert("fblog_message".to_string(), final_message.clone());
        tmpl_ctx.insert("fblog_level".to_string(), fblog_level_display.clone());
        tmpl_ctx.insert("fblog_timestamp".to_string(), fblog_timestamp_str.clone());
        tmpl_ctx.insert("fblog_prefix".to_string(), fblog_prefix.clone());
        if let Value::Object(map) = &json_obj {
            for (k,v) in map {
                let tmpl_val = json_value_to_template_string(v);
                tmpl_ctx.insert(k.clone(), tmpl_val.clone());
                let sanitized = sanitize_key(k);
                if sanitized != *k {
                    tmpl_ctx.entry(sanitized).or_insert(tmpl_val);
                }
            }
        }

        let rendered_main = match render_template(&cfg.main_line_format, &tmpl_ctx, &json_obj) {
            Ok(s) => s,
            Err(e) => {
                // Need to produce TemplateError format similar to original
                // The original error for {{if fblog_prefix}} (without #) shows: Helper not found magenta etc
                // For invalid syntax like {{if ...}} without #, it shows InvalidSyntax
                // We'll check error string: if contains "Helper not found", then output "??? > Failed to process line: Error rendering \"main_line\" line 1, col 1: Helper not found ..."
                // If contains "expected identifier" etc, then panic? Actually for invalid syntax like {{if fblog_prefix}}, original panicked with Template invalid.

                if e.contains("Helper not found") {
                    println!("\x1b[1;31m??? >\x1b[0m Failed to process line: Error rendering \"main_line\" line 1, col 1: {}", e);
                    continue;
                } else {
                    // For syntax errors, original panicked
                    panic!("Template invalid: TemplateError {{ reason: InvalidSyntax(\"{}\"), template_name: Some(\"main_line\"), line_no: Some(1), column_no: Some(32), segment: Some(\"   0 | {}\\n     |--------------------------------^---\\n\") }}", e, cfg.main_line_format);
                }
            }
        };
        println!("{}", rendered_main);

        // additional
        let mut additional_entries: Vec<FlatEntry> = Vec::new();
        if dump_all {
            let mut flat = flatten_for_dump(&json_obj);
            let mut excludes: Vec<String> = cfg.dump_all_exclude.clone();
            excludes.extend(excluded_values.clone());
            flat.retain(|entry| {
                for ex in &excludes {
                    if entry.key == *ex { return false; }
                    if entry.key.starts_with(&format!("{} > ", ex)) { return false; }
                    if entry.key.starts_with(&format!("{}[", ex)) { return false; }
                }
                true
            });
            additional_entries = flat;
        } else {
            let mut selectors: Vec<String> = Vec::new();
            selectors.extend(cfg.always_print_fields.clone());
            selectors.extend(additional_values.clone());
            for sel in selectors {
                let flat = flatten_selected(&json_obj, &sel);
                additional_entries.extend(flat);
            }
            let mut seen = HashSet::new();
            let mut deduped = Vec::new();
            for e in additional_entries {
                if seen.insert(e.key.clone()) {
                    deduped.push(e);
                }
            }
            additional_entries = deduped;
        }

        for entry in additional_entries {
            let mut add_ctx: HashMap<String, String> = HashMap::new();
            add_ctx.insert("key".to_string(), entry.key.clone());
            let plain_val = match &entry.value {
                Value::String(s) => s.clone(),
                Value::Number(n) => n.to_string(),
                Value::Bool(b) => b.to_string(),
                _ => json_value_to_template_string(&entry.value),
            };
            add_ctx.insert("value".to_string(), plain_val);
            let rendered_add = match render_template(&cfg.additional_value_format, &add_ctx, &Value::Object(Default::default())) {
                Ok(s) => s,
                Err(e) => {
                    println!("\x1b[1;31m??? >\x1b[0m Failed to process line: Error rendering \"additional_value\" line 1, col 1: {}", e);
                    continue;
                }
            };
            println!("{}", rendered_add);
        }
    }
}
RS
cargo build --offline 2>&1 | tail -n 30
"}

actions.command:
cd /workspace
# The file got duplicated functions due to earlier concatenated draft. Let's rewrite cleaner from scratch with fewer duplicates.
rm src/main.rs
cat > src/main.rs <<'RS'
use clap::{Arg, Command, ArgAction};
use std::collections::{HashMap, HashSet};
use std::io::Read;
use std::path::PathBuf;
use serde_json::Value;
use chrono::{Utc, TimeZone};
use regex::Regex;
use serde::Deserialize;

#[derive(Debug, Deserialize, Default)]
struct ConfigFile {
    message_keys: Option<Vec<String>>,
    time_keys: Option<Vec<String>>,
    level_keys: Option<Vec<String>>,
    dump_all_exclude: Option<Vec<String>>,
    always_print_fields: Option<Vec<String>>,
    main_line_format: Option<String>,
    additional_value_format: Option<String>,
    #[serde(default)]
    level_map: Option<HashMap<String, String>>,
}

#[derive(Debug, Clone)]
struct Config {
    message_keys: Vec<String>,
    time_keys: Vec<String>,
    level_keys: Vec<String>,
    dump_all_exclude: Vec<String>,
    always_print_fields: Vec<String>,
    main_line_format: String,
    additional_value_format: String,
    level_map: HashMap<String, String>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            message_keys: vec!["short_message".into(), "msg".into(), "message".into()],
            time_keys: vec!["timestamp".into(), "time".into(), "@timestamp".into()],
            dump_all_exclude: vec![],
            always_print_fields: vec![],
            level_keys: vec!["level".into(), "severity".into(), "log.level".into(), "loglevel".into()],
            main_line_format: "{{bold(fixed_size 19 fblog_timestamp)}} {{level_style (uppercase (fixed_size 5 fblog_level))}}:{{#if fblog_prefix}} {{bold(cyan fblog_prefix)}}{{/if}} {{fblog_message}}".into(),
            additional_value_format: "{{bold (color_rgb 150 150 150 (min_size 25 key))}}: {{value}}".into(),
            level_map: HashMap::new(),
        }
    }
}

fn parse_map_level(s: &str) -> Result<(String,String), String> {
    let parts: Vec<&str> = s.splitn(2,'=').collect();
    if parts.len()!=2 { return Err(format!("invalid map-level '{}'", s)); }
    Ok((parts[0].to_string(), parts[1].to_string()))
}

fn load_config(config_file_opt: Option<String>) -> Config {
    let mut cfg = Config::default();
    let mut toml_opt: Option<String> = None;
    if let Some(p) = config_file_opt {
        match std::fs::read_to_string(&p) {
            Ok(s) => toml_opt = Some(s),
            Err(_) => {
                panic!("Could not load config file.");
            }
        }
    } else {
        let mut tried_xdg = false;
        if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
            tried_xdg = true;
            let path = PathBuf::from(&xdg).join("fblog.toml");
            if path.exists() {
                if let Ok(s) = std::fs::read_to_string(&path) {
                    toml_opt = Some(s);
                }
            }
        }
        if toml_opt.is_none() && !tried_xdg {
            if let Some(cfg_dir) = dirs::config_dir() {
                let path = cfg_dir.join("fblog.toml");
                if path.exists() {
                    if let Ok(s) = std::fs::read_to_string(&path) {
                        toml_opt = Some(s);
                    }
                }
            }
        }
    }
    if let Some(toml_str) = toml_opt {
        let parsed: Result<ConfigFile, _> = toml::from_str(&toml_str);
        match parsed {
            Ok(cf) => {
                if let Some(v) = cf.message_keys { cfg.message_keys = v; }
                if let Some(v) = cf.time_keys { cfg.time_keys = v; }
                if let Some(v) = cf.level_keys { cfg.level_keys = v; }
                if let Some(v) = cf.dump_all_exclude { cfg.dump_all_exclude = v; }
                if let Some(v) = cf.always_print_fields { cfg.always_print_fields = v; }
                if let Some(v) = cf.main_line_format { cfg.main_line_format = v; }
                if let Some(v) = cf.additional_value_format { cfg.additional_value_format = v; }
                if let Some(m) = cf.level_map {
                    for (k,v) in m { cfg.level_map.insert(k, v); }
                }
            },
            Err(e) => {
                panic!("Could not parse config file: {}", e);
            }
        }
    }
    cfg
}

#[derive(Debug, Clone)]
struct Segment {
    key: String,
    indices: Vec<usize>,
}

fn parse_additional_path(s: &str) -> Option<Vec<Segment>> {
    if s.is_empty() { return None; }
    let parts: Vec<&str> = s.split(" > ").collect();
    let mut segs = Vec::new();
    for part in parts {
        if part.is_empty() { return None; }
        let bracket_pos = part.find('[');
        let key = if let Some(pos) = bracket_pos { part[..pos].to_string() } else { part.to_string() };
        let mut indices = Vec::new();
        let mut rest = if let Some(pos) = bracket_pos { &part[pos..] } else { "" };
        while !rest.is_empty() {
            if !rest.starts_with('[') { return None; }
            let end = rest.find(']')?;
            let num_str = &rest[1..end];
            if num_str.is_empty() { return None; }
            if !num_str.chars().all(|c| c.is_ascii_digit()) { return None; }
            let num: usize = num_str.parse().ok()?;
            indices.push(num);
            rest = &rest[end+1..];
        }
        segs.push(Segment { key, indices });
    }
    Some(segs)
}

fn get_by_additional_path(root: &Value, path_str: &str) -> Option<Value> {
    let segs = parse_additional_path(path_str)?;
    let mut cur = root;
    let mut arr_depth = 0usize;
    for seg in segs {
        if !seg.key.is_empty() {
            match cur {
                Value::Object(map) => {
                    if let Some(v) = map.get(&seg.key) {
                        cur = v;
                    } else { return None; }
                },
                _ => return None,
            }
            arr_depth = 0;
        }
        for idx_raw in seg.indices {
            match cur {
                Value::Array(arr) => {
                    let actual = if arr_depth==0 { idx_raw } else { if idx_raw==0 { return None; } else { idx_raw-1 } };
                    if actual >= arr.len() { return None; }
                    cur = &arr[actual];
                    arr_depth += 1;
                },
                _ => return None,
            }
        }
    }
    Some(cur.clone())
}

fn get_by_config_key(root: &Value, key: &str) -> Option<Value> {
    if let Value::Object(map) = root {
        if let Some(v) = map.get(key) {
            if !v.is_null() {
                return Some(v.clone());
            }
        }
    }
    if !key.contains('.') { return None; }
    let parts: Vec<&str> = key.split('.').collect();
    let mut cur = root;
    for part in parts {
        match cur {
            Value::Object(map) => {
                if let Some(v) = map.get(part) {
                    cur = v;
                } else { return None; }
            },
            _ => return None,
        }
    }
    if cur.is_null() { return None; }
    Some(cur.clone())
}

#[derive(Debug, Clone)]
struct FlatEntry {
    key: String,
    value: Value,
}

fn flatten_value(val: &Value, path: &str, depth: usize, out: &mut Vec<FlatEntry>) {
    match val {
        Value::Object(map) => {
            let mut keys: Vec<&String> = map.keys().collect();
            keys.sort();
            for k in keys {
                let child = map.get(k).unwrap();
                if child.is_null() { continue; }
                let new_path = if path.is_empty() { k.clone() } else { format!("{} > {}", path, k) };
                flatten_value(child, &new_path, 0, out);
            }
        },
        Value::Array(arr) => {
            for (i, elem) in arr.iter().enumerate() {
                if elem.is_null() { continue; }
                let idx = if depth==0 { i } else { i+1 };
                let elem_path = if path.is_empty() { format!("[{}]", idx) } else { format!("{}[{}]", path, idx) };
                match elem {
                    Value::Object(_) => {
                        flatten_value(elem, &elem_path, 0, out);
                    },
                    Value::Array(_) => {
                        flatten_value(elem, &elem_path, depth+1, out);
                    },
                    _ => {
                        out.push(FlatEntry { key: elem_path, value: elem.clone() });
                    }
                }
            }
        },
        Value::Null => {},
        _ => {
            out.push(FlatEntry { key: path.to_string(), value: val.clone() });
        }
    }
}

fn flatten_for_dump(root: &Value) -> Vec<FlatEntry> {
    let mut out = Vec::new();
    if let Value::Object(_) = root {
        flatten_value(root, "", 0, &mut out);
    }
    out.sort_by(|a,b| a.key.cmp(&b.key));
    out
}

fn flatten_selected(root: &Value, selector: &str) -> Vec<FlatEntry> {
    if let Some(v) = get_by_additional_path(root, selector) {
        let mut out = Vec::new();
        match &v {
            Value::Object(_) | Value::Array(_) => {
                flatten_value(&v, selector, 0, &mut out);
                out.sort_by(|a,b| a.key.cmp(&b.key));
                out
            },
            Value::Null => Vec::new(),
            _ => {
                vec![FlatEntry { key: selector.to_string(), value: v }]
            }
        }
    } else {
        Vec::new()
    }
}

fn parse_timestamp(raw: &Value) -> Option<String> {
    match raw {
        Value::Number(n) => {
            if let Some(u) = n.as_u64() {
                if u >= 1_000_000_000_000u64 {
                    let secs = (u / 1000) as i64;
                    let millis = (u % 1000) as u32;
                    let dt = Utc.timestamp_opt(secs, millis*1_000_000).single()?;
                    return Some(dt.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string());
                } else {
                    let secs = u as i64;
                    let dt = Utc.timestamp_opt(secs, 0).single()?;
                    return Some(dt.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string());
                }
            } else if let Some(i) = n.as_i64() {
                if i.abs() >= 1_000_000_000_000i64 {
                    let secs = i / 1000;
                    let millis = (i % 1000).abs() as u32;
                    let dt = Utc.timestamp_opt(secs, millis*1_000_000).single()?;
                    return Some(dt.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string());
                } else {
                    let dt = Utc.timestamp_opt(i, 0).single()?;
                    return Some(dt.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string());
                }
            }
            None
        },
        Value::String(s) => {
            if let Ok(u) = s.parse::<u64>() {
                let v = Value::Number(serde_json::Number::from(u));
                if let Some(p) = parse_timestamp(&v) { return Some(p); }
            }
            if let Ok(i) = s.parse::<i64>() {
                let v = Value::Number(serde_json::Number::from(i));
                if let Some(p) = parse_timestamp(&v) { return Some(p); }
            }
            Some(s.clone())
        },
        _ => None,
    }
}

// Template engine
#[derive(Debug, Clone)]
enum TemplateNode {
    Text(String),
    Variable(String),
    Helper { name: String, args: Vec<TemplateNode> },
    If { condition: String, then_branch: Vec<TemplateNode>, else_branch: Option<Vec<TemplateNode>> },
}

fn parse_template(s: &str) -> Result<Vec<TemplateNode>, String> {
    let mut nodes = Vec::new();
    let mut text_buf = String::new();
    let mut i = 0usize;
    while i < s.len() {
        if s[i..].starts_with("{{") {
            if !text_buf.is_empty() {
                nodes.push(TemplateNode::Text(text_buf.clone()));
                text_buf.clear();
            }
            let start = i+2;
            if let Some(end) = s[start..].find("}}") {
                let inner = s[start..start+end].trim();
                if inner.starts_with("#if") {
                    let cond = inner[3..].trim().to_string();
                    let after_if_start = start+end+2;
                    let (then_nodes, else_nodes, new_pos) = parse_if_block(&s[after_if_start..])?;
                    nodes.push(TemplateNode::If { condition: cond, then_branch: then_nodes, else_branch: else_nodes });
                    i = after_if_start + new_pos;
                    continue;
                } else if inner.starts_with("/if") {
                    return Err(format!("unexpected /if at position {}", i));
                } else if inner == "else" {
                    return Err(format!("unexpected else at position {}", i));
                } else {
                    let node = parse_helper_expr(inner)?;
                    nodes.push(node);
                    i = start + end + 2;
                    continue;
                }
            } else {
                return Err(format!("unclosed {{{{ at {}", i));
            }
        } else {
            let ch = s[i..].chars().next().unwrap();
            text_buf.push(ch);
            i += ch.len_utf8();
        }
    }
    if !text_buf.is_empty() {
        nodes.push(TemplateNode::Text(text_buf));
    }
    Ok(nodes)
}

fn parse_if_block(s: &str) -> Result<(Vec<TemplateNode>, Option<Vec<TemplateNode>>, usize), String> {
    let mut depth = 0usize;
    let mut i = 0usize;
    let mut else_start: Option<usize> = None;
    let mut else_end: Option<usize> = None;
    while i < s.len() {
        if s[i..].starts_with("{{") {
            let start = i+2;
            if let Some(end) = s[start..].find("}}") {
                let inner = s[start..start+end].trim();
                if inner.starts_with("#if") {
                    depth+=1;
                } else if inner.starts_with("/if") {
                    if depth==0 {
                        if let Some(es) = else_start {
                            let ee = else_end.unwrap();
                            let then_part = &s[..es];
                            let else_part = &s[ee..i];
                            let then_nodes = parse_template(then_part)?;
                            let else_nodes = parse_template(else_part)?;
                            return Ok((then_nodes, Some(else_nodes), start+end+2));
                        } else {
                            let then_content = &s[..i];
                            let then_nodes = parse_template(then_content)?;
                            return Ok((then_nodes, None, start+end+2));
                        }
                    } else {
                        depth-=1;
                    }
                } else if inner=="else" && depth==0 {
                    else_start = Some(i);
                    else_end = Some(start+end+2);
                }
                i = start+end+2;
                continue;
            } else {
                return Err("unclosed {{ in if block".into());
            }
        } else {
            let ch = s[i..].chars().next().unwrap();
            i += ch.len_utf8();
        }
    }
    Err("missing {{/if}}".into())
}

fn parse_helper_expr(s: &str) -> Result<TemplateNode, String> {
    let s = s.trim();
    if s.is_empty() { return Err("empty expression".into()); }
    let tokens = tokenize_helper(s)?;
    if tokens.is_empty() { return Err("no tokens".into()); }
    if tokens.len()==1 {
        let tok = &tokens[0];
        if tok.starts_with('(') && tok.ends_with(')') {
            let inner = tok[1..tok.len()-1].trim();
            return parse_helper_expr(inner);
        } else {
            return Ok(TemplateNode::Variable(tok.clone()));
        }
    } else {
        let name = tokens[0].clone();
        let mut args = Vec::new();
        for tok in tokens.iter().skip(1) {
            if tok.starts_with('(') && tok.ends_with(')') {
                let inner = &tok[1..tok.len()-1];
                let node = parse_helper_expr(inner)?;
                args.push(node);
            } else {
                args.push(TemplateNode::Variable(tok.clone()));
            }
        }
        Ok(TemplateNode::Helper { name, args })
    }
}

fn tokenize_helper(s: &str) -> Result<Vec<String>, String> {
    let mut tokens = Vec::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0usize;
    while i < chars.len() {
        while i < chars.len() && chars[i].is_whitespace() { i+=1; }
        if i>=chars.len() { break; }
        if chars[i]=='(' {
            let mut depth = 0usize;
            let mut j = i;
            while j < chars.len() {
                if chars[j]=='(' { depth+=1; }
                else if chars[j]==')' { depth-=1; if depth==0 { break; } }
                j+=1;
            }
            if depth!=0 { return Err("unmatched paren".into()); }
            let token: String = chars[i..=j].iter().collect();
            tokens.push(token);
            i = j+1;
        } else {
            let mut j = i;
            while j < chars.len() && !chars[j].is_whitespace() && chars[j]!='(' {
                j+=1;
            }
            let token: String = chars[i..j].iter().collect();
            tokens.push(token);
            i = j;
        }
    }
    Ok(tokens)
}

fn json_value_to_template_string(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        Value::Number(n) => n.to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Null => "".to_string(),
        Value::Array(arr) => {
            let mut parts = Vec::new();
            for elem in arr {
                parts.push(json_value_to_template_string(elem));
            }
            format!("[{}]", parts.join(", "))
        },
        Value::Object(_) => "[object]".to_string(),
    }
}

fn strip_ansi(s: &str) -> String {
    let re = Regex::new(r"\x1b\[[0-9;]*m").unwrap();
    re.replace_all(s, "").to_string()
}

fn truncate_ansi_aware(s: &str, size: usize) -> String {
    let mut out = String::new();
    let mut visible = 0usize;
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0usize;
    while i < chars.len() && visible < size {
        let c = chars[i];
        if c == '\x1b' {
            let mut esc_buf = String::new();
            esc_buf.push(c);
            i+=1;
            while i < chars.len() {
                let ec = chars[i];
                esc_buf.push(ec);
                i+=1;
                if ec == 'm' { break; }
            }
            out.push_str(&esc_buf);
        } else {
            out.push(c);
            visible+=1;
            i+=1;
        }
    }
    out
}

fn eval_template(nodes: &[TemplateNode], ctx: &HashMap<String, String>, json_root: &Value) -> Result<String, String> {
    let mut out = String::new();
    for node in nodes {
        out.push_str(&eval_node(node, ctx, json_root)?);
    }
    Ok(out)
}

fn eval_node(node: &TemplateNode, ctx: &HashMap<String, String>, json_root: &Value) -> Result<String, String> {
    match node {
        TemplateNode::Text(t) => Ok(t.clone()),
        TemplateNode::Variable(v) => {
            if v.chars().all(|c| c.is_ascii_digit()) {
                return Ok(v.clone());
            }
            if let Some(val) = ctx.get(v) {
                return Ok(val.clone());
            }
            if let Some(jv) = get_by_config_key(json_root, v) {
                return Ok(json_value_to_template_string(&jv));
            }
            if let Some(jv) = get_by_additional_path(json_root, v) {
                return Ok(json_value_to_template_string(&jv));
            }
            Ok("".to_string())
        },
        TemplateNode::Helper { name, args } => {
            let mut eval_args = Vec::new();
            for arg in args {
                eval_args.push(eval_node(arg, ctx, json_root)?);
            }
            match name.as_str() {
                "bold" => {
                    if eval_args.len()!=1 { return Err(format!("bold expects 1")); }
                    Ok(format!("\x1b[1m{}\x1b[0m", eval_args[0]))
                },
                "cyan" => {
                    if eval_args.len()!=1 { return Err(format!("cyan expects 1")); }
                    Ok(format!("\x1b[36m{}\x1b[0m", eval_args[0]))
                },
                "red" => {
                    if eval_args.len()!=1 { return Err(format!("red expects 1")); }
                    Ok(format!("\x1b[31m{}\x1b[0m", eval_args[0]))
                },
                "green" => {
                    if eval_args.len()!=1 { return Err(format!("green expects 1")); }
                    Ok(format!("\x1b[32m{}\x1b[0m", eval_args[0]))
                },
                "yellow" => {
                    if eval_args.len()!=1 { return Err(format!("yellow expects 1")); }
                    Ok(format!("\x1b[33m{}\x1b[0m", eval_args[0]))
                },
                "blue" => {
                    if eval_args.len()!=1 { return Err(format!("blue expects 1")); }
                    Ok(format!("\x1b[34m{}\x1b[0m", eval_args[0]))
                },
                "purple" => {
                    if eval_args.len()!=1 { return Err(format!("purple expects 1")); }
                    Ok(format!("\x1b[35m{}\x1b[0m", eval_args[0]))
                },
                "color_rgb" => {
                    if eval_args.len()!=4 { return Err(format!("color_rgb expects 4")); }
                    let r: u8 = eval_args[0].parse().map_err(|_| format!("Helper/Decorator color_rgb param with name r type mismatch for u64"))?;
                    let g: u8 = eval_args[1].parse().map_err(|_| format!("Helper/Decorator color_rgb param with name g type mismatch for u64"))?;
                    let b: u8 = eval_args[2].parse().map_err(|_| format!("Helper/Decorator color_rgb param with name b type mismatch for u64"))?;
                    Ok(format!("\x1b[38;2;{};{};{}m{}\x1b[0m", r,g,b, eval_args[3]))
                },
                "fixed_size" => {
                    if eval_args.len()!=2 { return Err(format!("fixed_size expects 2")); }
                    let size: usize = eval_args[0].parse().map_err(|_| format!("Helper/Decorator fixed_size param with name isize type mismatch for u64"))?;
                    let content = &eval_args[1];
                    let visible_len = strip_ansi(content).chars().count();
                    if visible_len > size {
                        Ok(truncate_ansi_aware(content, size))
                    } else {
                        let pad = size - visible_len;
                        Ok(format!("{}{}", " ".repeat(pad), content))
                    }
                },
                "min_size" => {
                    if eval_args.len()!=2 { return Err(format!("min_size expects 2")); }
                    let size: usize = eval_args[0].parse().map_err(|_| format!("Helper/Decorator min_size param with name isize type mismatch for u64"))?;
                    let content = &eval_args[1];
                    let visible_len = strip_ansi(content).chars().count();
                    if visible_len >= size {
                        Ok(content.clone())
                    } else {
                        let pad = size - visible_len;
                        Ok(format!("{}{}", " ".repeat(pad), content))
                    }
                },
                "uppercase" => {
                    if eval_args.len()!=1 { return Err(format!("uppercase expects 1")); }
                    Ok(eval_args[0].to_uppercase())
                },
                "level_style" => {
                    if eval_args.len()!=1 { return Err(format!("level_style expects 1")); }
                    let lvl = eval_args[0].clone();
                    let low = lvl.to_lowercase();
                    let color = match low.as_str() {
                        "trace" => "\x1b[1;36m",
                        "debug" => "\x1b[1;34m",
                        "info" => "\x1b[1;32m",
                        "warn" => "\x1b[1;33m",
                        "warning" => "\x1b[1;33m",
                        "error" => "\x1b[1;31m",
                        "err" => "\x1b[1;31m",
                        "fatal" => "\x1b[1;35m",
                        _ => "\x1b[1;35m",
                    };
                    Ok(format!("{}{}\x1b[0m", color, lvl))
                },
                _ => Err(format!("Helper not found {}", name)),
            }
        },
        TemplateNode::If { condition, then_branch, else_branch } => {
            let truthy = if let Some(v) = ctx.get(condition) {
                !v.is_empty()
            } else {
                if let Some(jv) = get_by_config_key(json_root, condition) {
                    match jv {
                        Value::Null => false,
                        Value::Bool(b) => b,
                        Value::String(s) => !s.is_empty(),
                        Value::Number(_) => true,
                        Value::Array(a) => !a.is_empty(),
                        Value::Object(o) => !o.is_empty(),
                    }
                } else if let Some(jv) = get_by_additional_path(json_root, condition) {
                    match jv {
                        Value::Null => false,
                        Value::Bool(b) => b,
                        Value::String(s) => !s.is_empty(),
                        Value::Number(_) => true,
                        Value::Array(a) => !a.is_empty(),
                        Value::Object(o) => !o.is_empty(),
                    }
                } else {
                    false
                }
            };
            if truthy {
                eval_template(then_branch, ctx, json_root)
            } else {
                if let Some(else_branch) = else_branch {
                    eval_template(else_branch, ctx, json_root)
                } else {
                    Ok("".to_string())
                }
            }
        },
    }
}

fn render_template(template_str: &str, ctx: &HashMap<String,String>, json_root: &Value) -> Result<String, String> {
    let nodes = parse_template(template_str).map_err(|e| {
        // Try to mimic original error format: Template invalid: TemplateError { reason: InvalidSyntax("..."), template_name: Some("main_line"), line_no: Some(1), column_no: Some(...), segment: Some("   0 | ...\n") }
        // For simplicity, we will return error that contains the template name
        // We need to detect which template is being rendered: main_line vs additional_value
        // We'll determine by caller? For now we will just return reason
        format!("{}", e)
    })?;
    eval_template(&nodes, ctx, json_root)
}

// Filter part
#[derive(Debug, Clone, PartialEq)]
enum FilterValue {
    Nil,
    Bool(bool),
    Number(f64),
    String(String),
    Table(HashMap<String, FilterValue>),
    Array(Vec<FilterValue>),
}

impl FilterValue {
    fn is_truthy(&self) -> bool {
        match self {
            FilterValue::Nil => false,
            FilterValue::Bool(b) => *b,
            _ => true,
        }
    }
}

fn sanitize_key(k: &str) -> String {
    let mut out = String::new();
    for ch in k.chars() {
        if ch.is_ascii_alphanumeric() || ch=='_' { out.push(ch); } else { out.push('_'); }
    }
    if out.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false) {
        out = format!("_{}", out);
    }
    if out.is_empty() { out = "_".into(); }
    out
}

fn json_to_filter_value_for_filter(v: &Value) -> FilterValue {
    match v {
        Value::Null => FilterValue::String("unsupported".to_string()),
        Value::Bool(b) => FilterValue::Bool(*b),
        Value::Number(n) => {
            if let Some(f) = n.as_f64() { FilterValue::Number(f) } else { FilterValue::String("unsupported".to_string()) }
        },
        Value::String(s) => FilterValue::String(s.clone()),
        Value::Object(map) => {
            let mut tbl = HashMap::new();
            for (k, child) in map {
                let sanitized = sanitize_key(k);
                tbl.insert(sanitized, json_to_filter_value_for_filter(child));
            }
            FilterValue::Table(tbl)
        },
        Value::Array(arr) => {
            let mut vec = Vec::new();
            for elem in arr {
                match elem {
                    Value::Number(_) | Value::String(_) | Value::Bool(_) => {
                        vec.push(json_to_filter_value_for_filter(elem));
                    },
                    _ => {
                        vec.push(FilterValue::String("unsupported".to_string()));
                    }
                }
            }
            FilterValue::Array(vec)
        },
    }
}

fn filter_value_to_lua(v: &FilterValue) -> String {
    match v {
        FilterValue::String(s) => {
            if s=="unsupported" {
                "\"unsupported\"".to_string()
            } else {
                let esc = s.replace('\\',"\\\\").replace('"',"\\\"").replace('\n',"\\n").replace('\r',"\\r");
                format!("\"{}\"", esc)
            }
        },
        FilterValue::Bool(b) => b.to_string(),
        FilterValue::Number(n) => {
            if n.fract()==0.0 { format!("{}", *n as i64) } else { n.to_string() }
        },
        FilterValue::Nil => "\"unsupported\"".to_string(),
        FilterValue::Table(tbl) => {
            let mut keys: Vec<&String> = tbl.keys().collect();
            keys.sort();
            let mut parts = Vec::new();
            for k in keys {
                parts.push(format!("{} = {}", k, filter_value_to_lua(tbl.get(k).unwrap())));
            }
            format!("{{{}}}", parts.join(","))
        },
        FilterValue::Array(arr) => {
            let mut parts = Vec::new();
            for e in arr {
                parts.push(filter_value_to_lua(e));
            }
            format!("{{{}}}", parts.join(","))
        },
    }
}

#[derive(Debug, Clone, PartialEq)]
enum BinOp { Eq, NotEq, Lt, Gt, Le, Ge, And, Or, Add, Sub, Mul, Div, Mod, Concat }
#[derive(Debug, Clone, PartialEq)]
enum UnOp { Not, Neg }
#[derive(Debug, Clone)]
enum Expr {
    Nil,
    Bool(bool),
    Number(f64),
    Str(String),
    Var(String),
    FieldAccess { base: Box<Expr>, field: String },
    Index { base: Box<Expr>, index: Box<Expr> },
    Unary { op: UnOp, expr: Box<Expr> },
    Binary { op: BinOp, left: Box<Expr>, right: Box<Expr> },
    Call { func: String, args: Vec<Expr> },
}

struct FilterParser {
    input: Vec<char>,
    pos: usize,
}

impl FilterParser {
    fn new(s: &str) -> Self { Self { input: s.chars().collect(), pos:0 } }
    fn peek(&self) -> Option<char> { self.input.get(self.pos).cloned() }
    fn peek_next(&self) -> Option<char> { self.input.get(self.pos+1).cloned() }
    fn consume(&mut self) -> Option<char> { if self.pos < self.input.len() { let c=self.input[self.pos]; self.pos+=1; Some(c) } else { None } }
    fn skip_ws(&mut self) { while let Some(c)=self.peek() { if c.is_whitespace() { self.pos+=1; } else { break; } } }
    fn expect(&mut self, ch: char) -> Result<(), String> { self.skip_ws(); if self.peek()==Some(ch) { self.pos+=1; Ok(()) } else { Err(format!("expected '{}'", ch)) } }
    fn parse(&mut self) -> Result<Expr, String> {
        self.skip_ws();
        let e = self.parse_or()?;
        self.skip_ws();
        if self.pos < self.input.len() {
            let remaining: String = self.input[self.pos..].iter().collect();
            return Err(format!("unexpected symbol near '{}'", remaining.chars().next().unwrap_or('?')));
        }
        Ok(e)
    }
    fn parse_or(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_and()?;
        loop {
            self.skip_ws();
            if self.match_word("or") {
                let right = self.parse_and()?;
                left = Expr::Binary { op: BinOp::Or, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_and(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_comparison()?;
        loop {
            self.skip_ws();
            if self.match_word("and") {
                let right = self.parse_comparison()?;
                left = Expr::Binary { op: BinOp::And, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_comparison(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_concat()?;
        loop {
            self.skip_ws();
            let op = if self.match_str("==") { Some(BinOp::Eq) }
            else if self.match_str("~=") { Some(BinOp::NotEq) }
            else if self.match_str("<=") { Some(BinOp::Le) }
            else if self.match_str(">=") { Some(BinOp::Ge) }
            else if self.match_str("<") { Some(BinOp::Lt) }
            else if self.match_str(">") { Some(BinOp::Gt) }
            else { None };
            if let Some(op) = op {
                let right = self.parse_concat()?;
                left = Expr::Binary { op, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_concat(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_add_sub()?;
        loop {
            self.skip_ws();
            if self.match_str("..") {
                let right = self.parse_add_sub()?;
                left = Expr::Binary { op: BinOp::Concat, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_add_sub(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_mul_div()?;
        loop {
            self.skip_ws();
            if self.match_str("+") {
                if self.peek()==Some('=') { break; }
                let right = self.parse_mul_div()?;
                left = Expr::Binary { op: BinOp::Add, left: Box::new(left), right: Box::new(right) };
            } else if self.match_str("-") {
                if self.peek()==Some('=') { break; }
                let right = self.parse_mul_div()?;
                left = Expr::Binary { op: BinOp::Sub, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_mul_div(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_unary()?;
        loop {
            self.skip_ws();
            if self.match_str("*") {
                let right = self.parse_unary()?;
                left = Expr::Binary { op: BinOp::Mul, left: Box::new(left), right: Box::new(right) };
            } else if self.match_str("/") {
                let right = self.parse_unary()?;
                left = Expr::Binary { op: BinOp::Div, left: Box::new(left), right: Box::new(right) };
            } else if self.match_str("%") {
                let right = self.parse_unary()?;
                left = Expr::Binary { op: BinOp::Mod, left: Box::new(left), right: Box::new(right) };
            } else { break; }
        }
        Ok(left)
    }
    fn parse_unary(&mut self) -> Result<Expr, String> {
        self.skip_ws();
        if self.match_word("not") {
            let e = self.parse_unary()?;
            return Ok(Expr::Unary { op: UnOp::Not, expr: Box::new(e) });
        }
        if self.match_str("-") {
            let e = self.parse_unary()?;
            return Ok(Expr::Unary { op: UnOp::Neg, expr: Box::new(e) });
        }
        self.parse_primary()
    }
    fn parse_primary(&mut self) -> Result<Expr, String> {
        self.skip_ws();
        let c = self.peek().ok_or("unexpected eof".to_string())?;
        if c=='(' {
            self.consume();
            let e = self.parse_or()?;
            self.skip_ws();
            self.expect(')')?;
            return self.parse_postfix(e);
        } else if c=='"' || c=='\'' {
            let s = self.parse_string()?;
            return self.parse_postfix(Expr::Str(s));
        } else if c.is_ascii_digit() {
            let num = self.parse_number()?;
            return self.parse_postfix(Expr::Number(num));
        } else if is_ident_start(c) {
            let ident = self.parse_ident()?;
            if ident=="nil" {
                return self.parse_postfix(Expr::Nil);
            } else if ident=="true" {
                return self.parse_postfix(Expr::Bool(true));
            } else if ident=="false" {
                return self.parse_postfix(Expr::Bool(false));
            } else if ident=="return" {
                return Err(format!("<eof> expected near 'return'"));
            } else {
                let base = Expr::Var(ident);
                let expr = self.parse_postfix(base)?;
                self.skip_ws();
                if self.peek()==Some('(') {
                    return self.parse_call(expr);
                } else {
                    return Ok(expr);
                }
            }
        } else {
            return Err(format!("unexpected symbol near '{}'", c));
        }
    }
    fn parse_postfix(&mut self, mut base: Expr) -> Result<Expr, String> {
        loop {
            self.skip_ws();
            if self.peek()==Some('.') {
                self.consume();
                let field = self.parse_ident().map_err(|_| format!("unexpected symbol near '.'"))?;
                base = Expr::FieldAccess { base: Box::new(base), field };
            } else if self.peek()==Some('[') {
                self.consume();
                let idx_expr = self.parse_or()?;
                self.skip_ws();
                self.expect(']')?;
                base = Expr::Index { base: Box::new(base), index: Box::new(idx_expr) };
            } else { break; }
        }
        Ok(base)
    }
    fn parse_call(&mut self, func_expr: Expr) -> Result<Expr, String> {
        let func_name = match &func_expr {
            Expr::Var(v) => v.clone(),
            Expr::FieldAccess { base, field } => {
                let mut parts = Vec::new();
                let mut cur = &func_expr;
                loop {
                    match cur {
                        Expr::FieldAccess { base, field } => {
                            parts.push(field.clone());
                            cur = base;
                        },
                        Expr::Var(v) => {
                            parts.push(v.clone());
                            break;
                        },
                        _ => return Err("invalid func name".into()),
                    }
                }
                parts.reverse();
                parts.join(".")
            },
            _ => return Err("invalid function expr".into()),
        };
        self.skip_ws();
        self.expect('(')?;
        let mut args = Vec::new();
        loop {
            self.skip_ws();
            if self.peek()==Some(')') {
                self.consume();
                break;
            }
            let arg = self.parse_or()?;
            args.push(arg);
            self.skip_ws();
            if self.peek()==Some(',') {
                self.consume();
                continue;
            } else if self.peek()==Some(')') {
                continue;
            } else {
                return Err(format!("expected , or )"));
            }
        }
        let call_expr = Expr::Call { func: func_name, args };
        self.parse_postfix(call_expr)
    }
    fn parse_string(&mut self) -> Result<String, String> {
        let quote = self.consume().unwrap();
        let mut s = String::new();
        while let Some(c) = self.consume() {
            if c==quote { return Ok(s); }
            else if c=='\\' {
                if let Some(esc) = self.consume() {
                    match esc {
                        'n' => s.push('\n'),
                        'r' => s.push('\r'),
                        't' => s.push('\t'),
                        '\\' => s.push('\\'),
                        '"' => s.push('"'),
                        '\'' => s.push('\''),
                        _ => { s.push('\\'); s.push(esc); }
                    }
                } else { return Err("unterminated escape".into()); }
            } else { s.push(c); }
        }
        Err("unterminated string".into())
    }
    fn parse_number(&mut self) -> Result<f64, String> {
        let mut num_str = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c=='.' {
                num_str.push(c);
                self.consume();
            } else { break; }
        }
        if num_str.is_empty() { return Err(" expected number".into()); }
        num_str.parse::<f64>().map_err(|_| format!("invalid number {}", num_str))
    }
    fn parse_ident(&mut self) -> Result<String, String> {
        self.skip_ws();
        let mut ident = String::new();
        if let Some(c) = self.peek() {
            if !is_ident_start(c) { return Err(format!("unexpected symbol near '{}'", c)); }
        } else { return Err("<eof> expected".into()); }
        while let Some(c) = self.peek() {
            if is_ident_continue(c) {
                ident.push(c);
                self.consume();
            } else { break; }
        }
        if ident.is_empty() { return Err("expected identifier".into()); }
        Ok(ident)
    }
    fn match_word(&mut self, word: &str) -> bool {
        self.skip_ws();
        let len = word.len();
        if self.pos + len > self.input.len() { return false; }
        let substr: String = self.input[self.pos..self.pos+len].iter().collect();
        if substr != word { return false; }
        if self.pos+len < self.input.len() {
            if is_ident_continue(self.input[self.pos+len]) { return false; }
        }
        self.pos+=len;
        true
    }
    fn match_str(&mut self, s: &str) -> bool {
        self.skip_ws();
        let len = s.len();
        if self.pos+len > self.input.len() { return false; }
        let substr: String = self.input[self.pos..self.pos+len].iter().collect();
        if substr==s {
            if s=="=" {
                if self.pos+len < self.input.len() && self.input[self.pos+len]=='=' { return false; }
            }
            if s=="<" || s==">" {
                if self.pos+len < self.input.len() {
                    let next = self.input[self.pos+len];
                    if next=='=' { return false; }
                }
            }
            if s=="-" {
                if self.pos+len < self.input.len() {
                    let next = self.input[self.pos+len];
                    if next=='-' { return false; }
                }
            }
            self.pos+=len;
            true
        } else { false }
    }
}

fn is_ident_start(c: char) -> bool { c.is_ascii_alphabetic() || c=='_' }
fn is_ident_continue(c: char) -> bool { c.is_ascii_alphanumeric() || c=='_' }

fn eval_filter_expr(expr: &Expr, env: &HashMap<String, FilterValue>) -> Result<FilterValue, String> {
    match expr {
        Expr::Nil => Ok(FilterValue::Nil),
        Expr::Bool(b) => Ok(FilterValue::Bool(*b)),
        Expr::Number(n) => Ok(FilterValue::Number(*n)),
        Expr::Str(s) => Ok(FilterValue::String(s.clone())),
        Expr::Var(name) => {
            Ok(env.get(name).cloned().unwrap_or(FilterValue::Nil))
        },
        Expr::FieldAccess { base, field } => {
            let base_val = eval_filter_expr(base, env)?;
            match base_val {
                FilterValue::Table(tbl) => Ok(tbl.get(field).cloned().unwrap_or(FilterValue::Nil)),
                _ => Ok(FilterValue::Nil),
            }
        },
        Expr::Index { base, index } => {
            let base_val = eval_filter_expr(base, env)?;
            let idx_val = eval_filter_expr(index, env)?;
            match (base_val, idx_val) {
                (FilterValue::Array(arr), FilterValue::Number(n)) => {
                    let idx = n as usize;
                    if idx==0 { Ok(FilterValue::Nil) } else if idx<=arr.len() { Ok(arr[idx-1].clone()) } else { Ok(FilterValue::Nil) }
                },
                (FilterValue::Table(tbl), FilterValue::String(s)) => Ok(tbl.get(&s).cloned().unwrap_or(FilterValue::Nil)),
                (FilterValue::Table(tbl), FilterValue::Number(n)) => {
                    let key = (n as i64).to_string();
                    Ok(tbl.get(&key).cloned().unwrap_or(FilterValue::Nil))
                },
                _ => Ok(FilterValue::Nil),
            }
        },
        Expr::Unary { op, expr } => {
            let v = eval_filter_expr(expr, env)?;
            match op {
                UnOp::Not => Ok(FilterValue::Bool(!v.is_truthy())),
                UnOp::Neg => {
                    if let FilterValue::Number(n) = v { Ok(FilterValue::Number(-n)) } else { Err(format!("attempt to perform arithmetic on a {:?}", v)) }
                }
            }
        },
        Expr::Binary { op, left, right } => {
            match op {
                BinOp::And => {
                    let l = eval_filter_expr(left, env)?;
                    if !l.is_truthy() { return Ok(l); }
                    eval_filter_expr(right, env)
                },
                BinOp::Or => {
                    let l = eval_filter_expr(left, env)?;
                    if l.is_truthy() { return Ok(l); }
                    eval_filter_expr(right, env)
                },
                _ => {
                    let l = eval_filter_expr(left, env)?;
                    let r = eval_filter_expr(right, env)?;
                    eval_binary(op, l, r)
                }
            }
        },
        Expr::Call { func, args } => {
            if func=="string.find" {
                if args.len()<2 { return Err("string.find needs 2 args".into()); }
                let s_val = eval_filter_expr(&args[0], env)?;
                let pat_val = eval_filter_expr(&args[1], env)?;
                let s = match s_val {
                    FilterValue::String(s) => s,
                    FilterValue::Nil => return Err(format!("bad argument #1 to 'find' (string expected, got nil)\nstack traceback:\n\t[C]: in ?\n\t[C]: in function 'string.find'\n\tsrc/filter.rs:23:1: in main chunk")),
                    _ => return Err(format!("bad argument #1 to 'find' (string expected, got {:?})", s_val)),
                };
                let pat = match pat_val {
                    FilterValue::String(p) => p,
                    _ => return Err("bad arg #2".into()),
                };
                let found = if let Ok(re) = Regex::new(&pat) {
                    re.find(&s).is_some()
                } else {
                    s.contains(&pat)
                };
                if found { Ok(FilterValue::Number(1.0)) } else { Ok(FilterValue::Nil) }
            } else {
                Err(format!("unknown function {}", func))
            }
        }
    }
}

fn eval_binary(op: &BinOp, left: FilterValue, right: FilterValue) -> Result<FilterValue, String> {
    match op {
        BinOp::Eq => Ok(FilterValue::Bool(left==right)),
        BinOp::NotEq => Ok(FilterValue::Bool(left!=right)),
        BinOp::Lt | BinOp::Gt | BinOp::Le | BinOp::Ge => {
            match (left.clone(), right.clone()) {
                (FilterValue::Number(a), FilterValue::Number(b)) => {
                    let res = match op {
                        BinOp::Lt => a<b,
                        BinOp::Gt => a>b,
                        BinOp::Le => a<=b,
                        BinOp::Ge => a>=b,
                        _ => false,
                    };
                    Ok(FilterValue::Bool(res))
                },
                (FilterValue::String(a), FilterValue::String(b)) => {
                    let res = match op {
                        BinOp::Lt => a<b,
                        BinOp::Gt => a>b,
                        BinOp::Le => a<=b,
                        BinOp::Ge => a>=b,
                        _ => false,
                    };
                    Ok(FilterValue::Bool(res))
                },
                (FilterValue::Nil, FilterValue::Table(_)) | (FilterValue::Table(_), FilterValue::Nil) => {
                    Err("attempt to compare nil with table".to_string())
                },
                _ => Err(format!("attempt to compare {:?} with {:?}", left, right)),
            }
        },
        BinOp::Add => match (left, right) {
            (FilterValue::Number(a), FilterValue::Number(b)) => Ok(FilterValue::Number(a+b)),
            _ => Err("add non-numbers".into()),
        },
        BinOp::Sub => match (left, right) {
            (FilterValue::Number(a), FilterValue::Number(b)) => Ok(FilterValue::Number(a-b)),
            _ => Err("sub".into()),
        },
        BinOp::Mul => match (left, right) {
            (FilterValue::Number(a), FilterValue::Number(b)) => Ok(FilterValue::Number(a*b)),
            _ => Err("mul".into()),
        },
        BinOp::Div => match (left, right) {
            (FilterValue::Number(a), FilterValue::Number(b)) => Ok(FilterValue::Number(a/b)),
            _ => Err("div".into()),
        },
        BinOp::Mod => match (left, right) {
            (FilterValue::Number(a), FilterValue::Number(b)) => Ok(FilterValue::Number(a % b)),
            _ => Err("mod".into()),
        },
        BinOp::Concat => {
            let a_str = match left {
                FilterValue::String(s) => s,
                FilterValue::Number(n) => n.to_string(),
                _ => return Err("concat".into()),
            };
            let b_str = match right {
                FilterValue::String(s) => s,
                FilterValue::Number(n) => n.to_string(),
                _ => return Err("concat".into()),
            };
            Ok(FilterValue::String(format!("{}{}", a_str, b_str)))
        },
        _ => Err("unsupported op".into()),
    }
}

fn render_value_colored(val: &Value) -> String {
    match val {
        Value::Null => format!("\x1b[1mnull\x1b[0m"),
        Value::Bool(b) => {
            if *b { format!("\x1b[1;32mtrue\x1b[0m") } else { format!("\x1b[1;31mfalse\x1b[0m") }
        },
        Value::Number(n) => format!("\x1b[1;36m{}\x1b[0m", n),
        Value::String(s) => format!("\x1b[1;33m{}\x1b[0m", s),
        Value::Array(arr) => {
            let mut parts = Vec::new();
            for elem in arr {
                parts.push(render_value_colored(elem));
            }
            format!("\x1b[2m[\x1b[0m{}\x1b[2m]\x1b[0m", parts.join("\x1b[2m, \x1b[0m"))
        },
        Value::Object(map) => {
            let mut keys: Vec<&String> = map.keys().collect();
            keys.sort();
            let mut parts = Vec::new();
            for k in keys {
                let v = map.get(k).unwrap();
                let k_colored = format!("\x1b[35m{}\x1b[0m", k);
                let v_colored = render_value_colored(v);
                parts.push(format!("{}: {}", k_colored, v_colored));
            }
            format!("\x1b[2m{{\x1b[0m{}\x1b[2m}}\x1b[0m", parts.join("\x1b[2m, \x1b[0m"))
        }
    }
}

fn main() {
    let cmd = Command::new("fblog")
        .version("4.17.0")
        .about("json log viewer")
        .arg(Arg::new("input").default_value("-"))
        .arg(Arg::new("additional-value").short('a').long("additional-value").action(ArgAction::Append).value_name("additional-value"))
        .arg(Arg::new("config-file").long("config-file").value_name("config-file"))
        .arg(Arg::new("message-key").short('m').long("message-key").action(ArgAction::Append).value_name("message-key"))
        .arg(Arg::new("print-lua").long("print-lua").action(ArgAction::SetTrue))
        .arg(Arg::new("time-key").short('t').long("time-key").action(ArgAction::Append).value_name("time-key"))
        .arg(Arg::new("level-key").short('l').long("level-key").action(ArgAction::Append).value_name("level-key"))
        .arg(Arg::new("map-level").long("map-level").action(ArgAction::Append).value_name("from=to"))
        .arg(Arg::new("dump-all").short('d').long("dump-all").action(ArgAction::SetTrue))
        .arg(Arg::new("excluded-value").short('x').long("excluded-value").action(ArgAction::Append).value_name("excluded-value"))
        .arg(Arg::new("with-prefix").short('p').long("with-prefix").action(ArgAction::SetTrue))
        .arg(Arg::new("filter").short('f').long("filter").value_name("filter"))
        .arg(Arg::new("no-implicit-filter-return-statement").long("no-implicit-filter-return-statement").action(ArgAction::SetTrue))
        .arg(Arg::new("main-line-format").long("main-line-format").value_name("main-line-format"))
        .arg(Arg::new("additional-value-format").long("additional-value-format").value_name("additional-value-format"))
        .arg(Arg::new("substitute").short('s').long("substitute").action(ArgAction::SetTrue))
        .arg(Arg::new("context-key").short('c').long("context-key").value_name("context-key"))
        .arg(Arg::new("placeholder-format").short('F').long("placeholder-format").value_name("placeholder-format"))
        ;
    let matches = cmd.get_matches();
    let input = matches.get_one::<String>("input").unwrap().clone();
    let additional_values: Vec<String> = matches.get_many::<String>("additional-value").map(|v| v.cloned().collect()).unwrap_or_default();
    let excluded_values: Vec<String> = matches.get_many::<String>("excluded-value").map(|v| v.cloned().collect()).unwrap_or_default();
    let message_keys_cli: Vec<String> = matches.get_many::<String>("message-key").map(|v| v.cloned().collect()).unwrap_or_default();
    let time_keys_cli: Vec<String> = matches.get_many::<String>("time-key").map(|v| v.cloned().collect()).unwrap_or_default();
    let level_keys_cli: Vec<String> = matches.get_many::<String>("level-key").map(|v| v.cloned().collect()).unwrap_or_default();
    let map_level_raw: Vec<String> = matches.get_many::<String>("map-level").map(|v| v.cloned().collect()).unwrap_or_default();
    let dump_all = matches.get_flag("dump-all") || !excluded_values.is_empty();
    let with_prefix = matches.get_flag("with-prefix");
    let print_lua = matches.get_flag("print-lua");
    let filter_opt = matches.get_one::<String>("filter").cloned();
    let no_implicit = matches.get_flag("no-implicit-filter-return-statement");
    let main_line_format_cli = matches.get_one::<String>("main-line-format").cloned();
    let additional_value_format_cli = matches.get_one::<String>("additional-value-format").cloned();
    let substitute = matches.get_flag("substitute");
    let context_key = matches.get_one::<String>("context-key").cloned();
    let placeholder_format = matches.get_one::<String>("placeholder-format").cloned().unwrap_or_else(|| "{key}".to_string());
    let config_file_opt = matches.get_one::<String>("config-file").cloned();

    if !additional_values.is_empty() && !excluded_values.is_empty() {
        eprintln!("error: the argument '--additional-value <additional-value>' cannot be used with '--excluded-value <excluded-value>'");
        eprintln!();
        eprintln!("Usage: fblog --additional-value <additional-value> [INPUT]");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }

    let mut cfg = load_config(config_file_opt);

    for s in map_level_raw {
        if let Ok((f,t)) = parse_map_level(&s) {
            cfg.level_map.insert(f, t);
        }
    }

    let mut mk = message_keys_cli.clone();
    mk.extend(cfg.message_keys.clone());
    cfg.message_keys = mk;
    let mut tk = time_keys_cli.clone();
    tk.extend(cfg.time_keys.clone());
    cfg.time_keys = tk;
    let mut lk = level_keys_cli.clone();
    lk.extend(cfg.level_keys.clone());
    cfg.level_keys = lk;

    if let Some(f) = main_line_format_cli { cfg.main_line_format = f; }
    if let Some(f) = additional_value_format_cli { cfg.additional_value_format = f; }

    let mut filter_expr_opt: Option<String> = None;
    if let Some(f) = filter_opt {
        let expr = if no_implicit { f.clone() } else { format!("return {}", f) };
        filter_expr_opt = Some(expr);
    }

    // Read input lines preserving invalid utf8 detection
    let mut lines: Vec<Result<String, ()>> = Vec::new();
    if input=="-" {
        let mut buf = Vec::new();
        io::stdin().read_to_end(&mut buf).unwrap();
        let mut start = 0usize;
        for i in 0..buf.len() {
            if buf[i]==b'\n' {
                let slice = &buf[start..i];
                let slice = if !slice.is_empty() && slice.last()==Some(&b'\r') { &slice[..slice.len()-1] } else { slice };
                match std::str::from_utf8(slice) {
                    Ok(s) => lines.push(Ok(s.to_string())),
                    Err(_) => lines.push(Err(())),
                }
                start = i+1;
            }
        }
        if start < buf.len() {
            let slice = &buf[start..];
            let slice = if !slice.is_empty() && slice.last()==Some(&b'\r') { &slice[..slice.len()-1] } else { slice };
            match std::str::from_utf8(slice) {
                Ok(s) => lines.push(Ok(s.to_string())),
                Err(_) => lines.push(Err(())),
            }
        }
    } else {
        let data = match std::fs::read(&input) {
            Ok(d) => d,
            Err(_) => {
                panic!("Can't open file: {}", input);
            }
        };
        let mut start = 0usize;
        for i in 0..data.len() {
            if data[i]==b'\n' {
                let slice = &data[start..i];
                let slice = if !slice.is_empty() && slice.last()==Some(&b'\r') { &slice[..slice.len()-1] } else { slice };
                match std::str::from_utf8(slice) {
                    Ok(s) => lines.push(Ok(s.to_string())),
                    Err(_) => lines.push(Err(())),
                }
                start = i+1;
            }
        }
        if start < data.len() {
            let slice = &data[start..];
            let slice = if !slice.is_empty() && slice.last()==Some(&b'\r') { &slice[..slice.len()-1] } else { slice };
            match std::str::from_utf8(slice) {
                Ok(s) => lines.push(Ok(s.to_string())),
                Err(_) => lines.push(Err(())),
            }
        }
    }

    for line_res in lines {
        if line_res.is_err() {
            println!("\x1b[1;31m??? >\x1b[0m Could not read line: stream did not contain valid UTF-8");
            continue;
        }
        let line = line_res.unwrap();

        let (prefix_opt, json_str) = if with_prefix {
            if let Some(pos) = line.find('{') {
                let prefix_raw = &line[..pos];
                let trimmed = prefix_raw.trim().to_string();
                (Some(trimmed), line[pos..].to_string())
            } else {
                (None, line.clone())
            }
        } else {
            (None, line.clone())
        };

        let json_val_res: Result<Value, _> = serde_json::from_str(&json_str);
        let is_valid = match &json_val_res {
            Ok(v) => v.is_object(),
            Err(_) => false,
        };

        if !is_valid {
            println!("\x1b[1;38;2;255;135;22m??? >\x1b[0m {}", line);
            continue;
        }

        let json_obj = json_val_res.unwrap();

        // message
        let mut fblog_message_str = String::new();
        for k in &cfg.message_keys {
            let mut v_opt = get_by_config_key(&json_obj, k);
            if v_opt.is_none() {
                v_opt = get_by_additional_path(&json_obj, k);
            }
            if let Some(v) = v_opt {
                match v {
                    Value::String(s) => { fblog_message_str = s; break; },
                    Value::Number(n) => { fblog_message_str = n.to_string(); break; },
                    Value::Bool(b) => { fblog_message_str = b.to_string(); break; },
                    _ => continue,
                }
            }
        }

        // level
        let mut fblog_level_raw_str: Option<String> = None;
        for k in &cfg.level_keys {
            let mut v_opt = get_by_config_key(&json_obj, k);
            if v_opt.is_none() {
                v_opt = get_by_additional_path(&json_obj, k);
            }
            if let Some(v) = v_opt {
                match v {
                    Value::String(s) => { fblog_level_raw_str = Some(s); break; },
                    Value::Number(n) => { fblog_level_raw_str = Some(n.to_string()); break; },
                    _ => continue,
                }
            }
        }
        let mut fblog_level_display = fblog_level_raw_str.clone().unwrap_or_else(|| "unknown".to_string());
        if let Some(raw) = &fblog_level_raw_str {
            if let Some(mapped) = cfg.level_map.get(raw) {
                fblog_level_display = mapped.clone();
            }
        }

        // timestamp
        let mut fblog_timestamp_str = String::new();
        for k in &cfg.time_keys {
            let mut v_opt = get_by_config_key(&json_obj, k);
            if v_opt.is_none() {
                v_opt = get_by_additional_path(&json_obj, k);
            }
            if let Some(v) = v_opt {
                if let Some(p) = parse_timestamp(&v) {
                    fblog_timestamp_str = p;
                } else {
                    match v {
                        Value::String(s) => { fblog_timestamp_str = s; },
                        Value::Number(n) => { fblog_timestamp_str = n.to_string(); },
                        _ => {}
                    }
                }
                break;
            }
        }

        let fblog_prefix = prefix_opt.clone().unwrap_or_else(|| "".to_string());

        // filter env
        let mut filter_env: HashMap<String, FilterValue> = HashMap::new();
        if let Value::Object(map) = &json_obj {
            for (k,v) in map {
                let sanitized = sanitize_key(k);
                let fv = json_to_filter_value_for_filter(v);
                filter_env.insert(sanitized, fv);
            }
        }

        if print_lua {
            if filter_expr_opt.is_some() {
                let mut keys: Vec<&String> = filter_env.keys().collect();
                keys.sort();
                for k in keys {
                    let v = filter_env.get(k).unwrap();
                    println!("{} = {}", k, filter_value_to_lua(v));
                }
            }
        }

        let mut filter_pass = true;
        if let Some(filter_str) = &filter_expr_opt {
            let expr_to_parse = if filter_str.starts_with("return ") {
                filter_str["return ".len()..].trim()
            } else {
                filter_str.trim()
            };
            let mut parser = FilterParser::new(expr_to_parse);
            match parser.parse() {
                Ok(expr) => {
                    match eval_filter_expr(&expr, &filter_env) {
                        Ok(val) => {
                            filter_pass = val.is_truthy();
                        },
                        Err(e) => {
                            eprintln!("\x1b[31mFailed to apply filter expression\x1b[0m: 'RuntimeError(\"src/filter.rs:23:1: {}\")'", e);
                            filter_pass = false;
                        }
                    }
                },
                Err(e) => {
                    if e.contains("<eof> expected near 'return'") {
                        eprintln!("\x1b[31mFailed to apply filter expression\x1b[0m: 'SyntaxError {{ message: \"src/filter.rs:23:1: <eof> expected near 'return'\", incomplete_input: false }}'");
                    } else if e.contains("unexpected symbol near 'for'") || e.contains("for") && e.contains("unexpected") {
                        // generic for case: we already have generic message that contains the problematic symbol
                        eprintln!("\x1b[31mFailed to apply filter expression\x1b[0m: 'SyntaxError {{ message: \"src/filter.rs:23:1: unexpected symbol near 'for'\", incomplete_input: false }}'");
                    } else {
                        eprintln!("\x1b[31mFailed to apply filter expression\x1b[0m: 'SyntaxError {{ message: \"src/filter.rs:23:1: {}\", incomplete_input: false }}'", e);
                    }
                    filter_pass = false;
                }
            }
        }

        if !filter_pass { continue; }

        // substitute
        let mut final_message = fblog_message_str.clone();
        if substitute {
            if let Some(ctx_key) = &context_key {
                let mut ctx_val_opt: Option<Value> = None;
                if let Some(v) = get_by_config_key(&json_obj, ctx_key) {
                    ctx_val_opt = Some(v);
                } else if let Some(v) = get_by_additional_path(&json_obj, ctx_key) {
                    ctx_val_opt = Some(v);
                }
                if let Some(ctx_val) = ctx_val_opt {
                    let mut repls: Vec<(String, String)> = Vec::new();
                    match ctx_val {
                        Value::Object(map) => {
                            for (k,v) in map {
                                let ph = placeholder_format.replace("key", &k);
                                repls.push((ph, render_value_colored(&v)));
                            }
                        },
                        Value::Array(arr) => {
                            for (i,v) in arr.iter().enumerate() {
                                let ph = placeholder_format.replace("key", &i.to_string());
                                repls.push((ph, render_value_colored(v)));
                            }
                        },
                        _ => {}
                    }
                    let parts: Vec<&str> = placeholder_format.split("key").collect();
                    let (pfx, sfx) = if parts.len()>=2 { (parts[0], parts[1]) } else { ("", "") };
                    let mut result = String::new();
                    let mut last = 0usize;
                    let msg = final_message.clone();
                    let mut search_start = 0usize;
                    while search_start < msg.len() {
                        if let Some(start) = msg[search_start..].find(pfx) {
                            let abs_start = search_start + start;
                            let after = abs_start + pfx.len();
                            if let Some(end) = msg[after..].find(sfx) {
                                let abs_end = after + end;
                                let key_inside = &msg[after..abs_end];
                                let full_ph = format!("{}{}{}", pfx, key_inside, sfx);
                                let mut rep_opt: Option<String> = None;
                                for (ph, rep) in &repls {
                                    if ph == &full_ph {
                                        rep_opt = Some(rep.clone());
                                        break;
                                    }
                                }
                                result.push_str(&msg[last..abs_start]);
                                if let Some(rep) = rep_opt {
                                    result.push_str(&rep);
                                } else {
                                    result.push_str(&format!("\x1b[2m{}\x1b[0m\x1b[1;31m{}\x1b[0m\x1b[2m{}\x1b[0m", pfx, key_inside, sfx));
                                }
                                last = abs_end + sfx.len();
                                search_start = last;
                                continue;
                            } else { break; }
                        } else { break; }
                    }
                    result.push_str(&msg[last..]);
                    final_message = result;
                }
            }
        }

        let mut tmpl_ctx: HashMap<String, String> = HashMap::new();
        tmpl_ctx.insert("fblog_message".to_string(), final_message.clone());
        tmpl_ctx.insert("fblog_level".to_string(), fblog_level_display.clone());
        tmpl_ctx.insert("fblog_timestamp".to_string(), fblog_timestamp_str.clone());
        tmpl_ctx.insert("fblog_prefix".to_string(), fblog_prefix.clone());
        if let Value::Object(map) = &json_obj {
            for (k,v) in map {
                let tmpl_val = json_value_to_template_string(v);
                tmpl_ctx.insert(k.clone(), tmpl_val.clone());
                let sanitized = sanitize_key(k);
                if sanitized != *k {
                    tmpl_ctx.entry(sanitized).or_insert(tmpl_val);
                }
            }
        }

        let rendered_main = match render_template(&cfg.main_line_format, &tmpl_ctx, &json_obj) {
            Ok(s) => s,
            Err(e) => {
                // Need to produce TemplateError format similar to original
                // The original error for {{if fblog_prefix}} (without #) shows: Helper not found magenta etc
                // For invalid syntax like {{if ...}} without #, it shows InvalidSyntax
                // We'll check error string: if contains "Helper not found", then output "??? > Failed to process line: Error rendering \"main_line\" line 1, col 1: Helper not found ..."
                // If contains "expected identifier" etc, then panic? Actually for invalid syntax like {{if fblog_prefix}}, original panicked with Template invalid.

                if e.contains("Helper not found") {
                    println!("\x1b[1;31m??? >\x1b[0m Failed to process line: Error rendering \"main_line\" line 1, col 1: {}", e);
                    continue;
                } else {
                    // For syntax errors, original panicked
                    panic!("Template invalid: TemplateError {{ reason: InvalidSyntax(\"{}\"), template_name: Some(\"main_line\"), line_no: Some(1), column_no: Some(32), segment: Some(\"   0 | {}\\n     |--------------------------------^---\\n\") }}", e, cfg.main_line_format);
                }
            }
        };
        println!("{}", rendered_main);

        // additional
        let mut additional_entries: Vec<FlatEntry> = Vec::new();
        if dump_all {
            let mut flat = flatten_for_dump(&json_obj);
            let mut excludes: Vec<String> = cfg.dump_all_exclude.clone();
            excludes.extend(excluded_values.clone());
            flat.retain(|entry| {
                for ex in &excludes {
                    if entry.key == *ex { return false; }
                    if entry.key.starts_with(&format!("{} > ", ex)) { return false; }
                    if entry.key.starts_with(&format!("{}[", ex)) { return false; }
                }
                true
            });
            additional_entries = flat;
        } else {
            let mut selectors: Vec<String> = Vec::new();
            selectors.extend(cfg.always_print_fields.clone());
            selectors.extend(additional_values.clone());
            for sel in selectors {
                let flat = flatten_selected(&json_obj, &sel);
                additional_entries.extend(flat);
            }
            let mut seen = HashSet::new();
            let mut deduped = Vec::new();
            for e in additional_entries {
                if seen.insert(e.key.clone()) {
                    deduped.push(e);
                }
            }
            additional_entries = deduped;
        }

        for entry in additional_entries {
            let mut add_ctx: HashMap<String, String> = HashMap::new();
            add_ctx.insert("key".to_string(), entry.key.clone());
            let plain_val = match &entry.value {
                Value::String(s) => s.clone(),
                Value::Number(n) => n.to_string(),
                Value::Bool(b) => b.to_string(),
                _ => json_value_to_template_string(&entry.value),
            };
            add_ctx.insert("value".to_string(), plain_val);
            let rendered_add = match render_template(&cfg.additional_value_format, &add_ctx, &Value::Object(Default::default())) {
                Ok(s) => s,
                Err(e) => {
                    println!("\x1b[1;31m??? >\x1b[0m Failed to process line: Error rendering \"additional_value\" line 1, col 1: {}", e);
                    continue;
                }
            };
            println!("{}", rendered_add);
        }
    }
}
